INSERT INTO `tour_package_images` VALUES (2,1,'tour-packages/gallery/01KM8APR48TVX35611QCX0AKV0.jpg',1,'2026-03-21 06:52:40','2026-03-28 00:49:52'),(6,2,'tour-packages/gallery/01KN27BHH3PRQK1TGT1B41R19G.jpg',1,'2026-03-28 00:47:43','2026-03-31 15:14:22'),(16,7,'tour-packages/gallery/01KMSDSQ714VNRP527QXGSJ9A7.jpg',1,'2026-03-28 05:13:48','2026-03-28 05:13:48'),(17,7,'tour-packages/gallery/01KMSDSQ731F908XRGYN7HQ6R0.jpg',2,'2026-03-28 05:13:48','2026-03-28 05:13:48'),(18,8,'tour-packages/gallery/01KMWFFJTE89JNZVMYQTSASE77.jpg',1,'2026-03-29 09:40:56','2026-03-29 09:40:56'),(19,8,'tour-packages/gallery/01KMWFFJTFX830V1GVPS5ECX8E.jpg',2,'2026-03-29 09:40:57','2026-03-29 09:40:57'),(20,9,'tour-packages/gallery/01KMWGEPRRGK3VFPD3NW9CZDWR.jpg',1,'2026-03-29 09:57:56','2026-03-29 09:57:56'),(21,9,'tour-packages/gallery/01KMWGEPRSPR55MXYY9X19WG3J.jpg',2,'2026-03-29 09:57:57','2026-03-29 09:57:57'),(24,11,'tour-packages/gallery/01KMWHFNYZ8P3YQY52PK3MA4WA.jpg',1,'2026-03-29 10:15:57','2026-03-29 10:15:57'),(25,11,'tour-packages/gallery/01KMWHFNZ06F8W3WAVCM8RWS9D.jpg',2,'2026-03-29 10:15:57','2026-03-29 10:15:57'),(26,12,'tour-packages/gallery/01KMWHQH3CSGFZM6A0EJZT1EB6.jpg',1,'2026-03-29 10:20:14','2026-03-29 10:20:14'),(27,12,'tour-packages/gallery/01KMWHQH3DCEVSMYJPFWR70X9T.jpg',2,'2026-03-29 10:20:14','2026-03-29 10:20:14'),(28,2,'tour-packages/gallery/01KN27FWGQM0TDFJ29STHYMX2A.jpg',2,'2026-03-31 15:16:44','2026-03-31 15:16:44'),(29,13,'tour-packages/gallery/01KN29MP1WKQRZZY0J5241HE7V.jpg',1,'2026-03-31 15:54:19','2026-03-31 15:54:19'),(30,13,'tour-packages/gallery/01KN29MP1XEBJP9WGF653G9T7M.jpg',2,'2026-03-31 15:54:19','2026-03-31 15:54:19'),(31,2,'tour-packages/gallery/01KN2AD8K2G3G5885GWPE7RF7J.jpg',3,'2026-03-31 16:07:44','2026-03-31 16:07:44'),(33,13,'tour-packages/gallery/01KN2ATNVQH3H33E553G6Y9DC2.jpg',3,'2026-03-31 16:15:04','2026-05-27 08:23:44'),(34,14,'tour-packages/gallery/01KN2G40BVVWWJ2XC7SH42DJKF.jpg',1,'2026-03-31 17:47:32','2026-03-31 17:47:32'),(35,14,'tour-packages/gallery/01KN2G40BWZFT80GR7HP30PGN8.jpg',2,'2026-03-31 17:47:32','2026-03-31 17:47:32'),(39,28,'tour-packages/gallery/01KP1AABK68HV7QX91689EE2Q2.png',1,'2026-04-12 17:02:36','2026-04-12 17:02:36'),(41,28,'tour-packages/gallery/01KP1AKQVM6M79FAQM9G4BM116.png',2,'2026-04-12 17:07:44','2026-04-12 17:07:44');
