--
-- Table structure for table `tour_packages`
--

DROP TABLE IF EXISTS `tour_packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tour_packages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `site_id` bigint unsigned NOT NULL DEFAULT '1',
  `tour_category_id` bigint unsigned NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `highlights` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `itinerary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `includes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `excludes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `pickup_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `terms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `thumbnail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `price_2_4` decimal(12,2) DEFAULT NULL COMMENT 'Price per person for 2-4 guests',
  `price_5_7` decimal(12,2) DEFAULT NULL COMMENT 'Price per person for 5-7 guests',
  `price_8_14` decimal(12,2) DEFAULT NULL COMMENT 'Price per person for 8-14 guests',
  `discounted_price` decimal(12,2) DEFAULT NULL,
  `duration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sub_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rating` decimal(2,1) DEFAULT NULL,
  `badge_icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `badge_label` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tour_packages_slug_unique` (`slug`),
  KEY `tour_packages_tour_category_id_foreign` (`tour_category_id`),
  KEY `tour_packages_site_id_index` (`site_id`),
  CONSTRAINT `tour_packages_tour_category_id_foreign` FOREIGN KEY (`tour_category_id`) REFERENCES `tour_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tour_packages`
--

LOCK TABLES `tour_packages` WRITE;
/*!40000 ALTER TABLE `tour_packages` DISABLE KEYS */;
INSERT INTO `tour_packages` VALUES (1,1,1,'Nusa Penida East Day Tour','Unveil the untouched wonders of East Nusa Penida — dramatic cliffs, pristine beaches, and dreamlike views await.','nusa-penida-east-day-tour','Discover the untouched beauty of East Nusa Penida on a breathtaking full-day island adventure.\nFrom the iconic cliffs of Diamond Beach to the peaceful charm of Atuh Beach and the panoramic ocean views from the famous Tree House, this tour offers some of the most stunning landscapes in Bali’s island paradise.\nPerfect for nature lovers, photographers, and travelers looking for a scenic tropical escape with fast boat transfers, private transport, and lunch included','1. Explore the most iconic and remote spots in East Penida\n2. Climb down to Diamond Beach for epic photos and a refreshing dip\n3. Visit the famous cliffside treehouse and marvel at the panoramic views\n4. Ideal for nature lovers, photographers, and peaceful explorers\n5. Escape the crowds and embrace the untouched side of Bali','1. Diamond Beach - A postcard-perfect beach with crystal waters and iconic stairway access carved into the cliffs.\n2. Atuh Beach - A serene crescent bay surrounded by limestone arches and dramatic cliffside views.\n3. Tree House (Rumah Pohon Molenteng) - Perched on a cliff edge, this famous treehouse offers panoramic views of the sea and surrounding islands.','1. Return fast boat ticket (Bali - Nusa Penida)\n2. All entrance fees\n3. Hotel Transfers\n4. Mineral water\n5. Lunch\n6. English speaking driver\n7. Private air-conditioned vehicle','1. Personal Expenses\n2. Any activities at destinations',NULL,'Maximum 5 persons per car (include driver / guide)\nPlease contact us prior to your booking date for smooth arrangements\nBring sunscreen and some cash for personal expenses\nNot wheelchair accessible\nThis experience requires good weather. If it’s canceled due to poor weather, you’ll be offered a different date or a full refund\nContact us for pickup outside the designated areas\nBe aware that some areas might be crowded based on holiday periods','tour-packages/01KN34Q86KXWNRFRBTZ6X68PRE.png',1000000.00,1402000.00,1357000.00,1250000.00,800000.00,'1 Day','Bali','Island Tour',4.9,'fa-camera','Beach ',1,1,49,'2026-03-21 05:52:00','2026-08-04 08:27:18'),(2,1,1,'West Nusa Penida Highlights Tour','Explore the raw beauty of Nusa Penida’s iconic west coast in one unforgettable day.','west-nusa-penida-highlights-tour','Discover the most iconic spots on West Nusa Penida in one easy day trip.\nEnjoy stunning cliff views, clear blue waters, and a smooth journey with fast boat and private car.\nPerfect for couples, families, or small groups who want beautiful scenery and great photos','1. Ideal for stunning travel photos and Instagram-worthy moments\n2. Comfortable round-trip fast boat from Bali\n3. Private driver and car for a personalized experience\n4. Perfect mix of adventure and relaxation\n5. Great for couples, groups, and solo explorers','Kelingking Beach\nBroken Beach\nAngel’s Billabong','1. Return fast boat ticket (Bali - Nusa Penida)\n2. All entrance fees\n3. Hotel Transfers\n4. Mineral water\n5. Lunch\n6. English speaking driver\n7. Private air-conditioned vehicle\n8. Private car 10 hours','1. Personal Expenses\n2. Any activities at destinations\n3. Overtime not included (extra charge applies)',NULL,'Maximum 5 persons per car (include driver / guide)\nPlease contact us prior to your booking date for smooth arrangements\nBring sunscreen and some cash for personal expenses\nNot wheelchair accessible\nThis experience requires good weather. If it’s canceled due to poor weather, you’ll be offered a different date or a full refund\nContact us for pickup outside the designated areas\nBe aware that some areas might be crowded based on holiday periods','tour-packages/01KN2F71SR504S8CYZEA7TRD4M.png',1080000.00,1200000.00,1155000.00,1050000.00,845000.00,'1 Day','Bali','Island Tour',5.0,'fa-camera','Photography',1,1,46,'2026-03-24 03:02:19','2026-08-04 08:20:22'),(3,1,1,'Snorkeling Paradise Nusa Penida','Dive into crystal-clear waters and discover the island’s famous coastal wonders — all in one unforgettable day.','snorkeling-paradise-nusa-penida','Snorkeling Paradise is the perfect blend of land exploration and marine adventure. Begin your day exploring the dramatic cliffs and natural rock formations of Nusa Penida’s west coast,\nthen dive beneath the surface to experience some of Bali’s best snorkeling spots teeming with colorful coral reefs and vibrant marine life.','1. A combination of sightseeing and ocean exploration in one tour\n2. Visit 3 iconic land destinations + 2–3 snorkeling points\n3. Ideal for nature lovers, photographers, and underwater explorers\n4. All snorkeling gear included\n5. Safe, guided, and beginner-friendly snorkeling experience','1. Kelingking beach - The island’s most iconic cliff viewpoint, shaped like a T-Rex and offering panoramic views of the Indian Ocean.\n2. Broken Beach - A natural arch over turquoise waters, perfect for striking landscape photos.\n3. Angel\'s Billabong - A natural tide pool and infinity lagoon carved into the rock, ideal for stunning visuals.\n4. Snorkeling Locations (may vary based on sea conditions):\nCrystal Bay – Calm waters, healthy coral, and a great chance to spot tropical fish.\nGamat Bay or Wall Point – Colorful reef walls and shallow snorkeling perfect for beginners and marine life lovers.\nManta bay - The island\'s most famous snorkeling and diving site where you can encounter majestic manta rays gliding gracefully in their natural habitat, along with a vibrant variety of tropical marine life.','1. Return fast boat ticket (Bali - Nusa Penida)\n2. All entrance fees\n3. Snorkeling boat & local guide\n4. Full snorkeling equipment (mask, fins, life jacket)\n5. Lunch\n6. Mineral water\n6. English speaking driver\n7. Private air-conditioned vehicle','1. Personal Expenses\n2. Gratuities',NULL,'Maximum 5 persons per car (include driver / guide)\nPlease contact us prior to your booking date for smooth arrangements\nBring sunscreen and some cash for personal expenses\nNot wheelchair accessible\nThis experience requires good weather. If it’s canceled due to poor weather, you’ll be offered a different date or a full refund\nContact us for pickup outside the designated areas\nBe aware that some areas might be crowded based on holiday periods','tour-packages/01KN2FEM6KAV6P7T66S25XF1DF.png',1162500.00,1350000.00,1305000.00,1200000.00,980000.00,'1 Day','Bali','Island Tour',5.0,'fa-mask-snorkel','snorkel',1,0,45,'2026-03-28 00:55:28','2026-08-04 08:22:42'),(4,1,1,'Ubud Ultimate Adventure Escape','Ubud Ultimate Adventure: ATV, Rafting & Swing Escape','ubud-ultimate-adventure-escape','Experience the ultimate adrenaline-filled journey through the heart of Ubud’s tropical paradise.\nRide powerful ATVs across jungle tunnels and muddy tracks, tackle exciting white-water rapids, and capture breathtaking moments above the treetops on the famous Ubud Swing.\nBalanced with scenic rice terrace views and a riverside lunch, this full-day adventure is crafted for thrill seekers who want Bali’s wild side in one unforgettable experience.','1. Full-day adventure in Bali’s lush highlands\n2. Combination of ATV + Rafting = double the thrill\n3. Includes Ubud’s most scenic spots for perfect photo opportunities\n4. Ideal for adventure seekers, couples, and groups of friends\n5. Safe, guided activities with professional instructors','1. ATV Ride - Get muddy and wild as you ride your own quad bike through forests, rivers, tunnels, and rice fields.\n2. White Water Rafting (2 hours) - Paddle through fun rapids along a jungle river with expert guides.\n3. Lunch  - Enjoy a delicious buffet lunch surrounded \n4. Ubud Swing - Take in panoramic views of the jungle as you swing high above the trees — an unforgettable moment.\n5. Tegalalang Rice Terrace - End the day with a relaxing stroll and scenic photo session in Bali’s famous rice fields.','1. Hotel pickup and drop-off\n2. All entrance fees\n3. Ubud swing ticket\n4. Mineral water\n5. Lunch\n6. English speaking driver\n7. Private air-conditioned vehicle (10 hours)\n8. ATV ride with safety gear & guide\n9. 2-hour white water rafting with guide & full equipment\n10. ','1. Personal Expenses\n2. Tips for the guide\n3. Overtime charge',NULL,'Minimum 2 participants required per booking\nPlease contact us prior to your booking date for smooth arrangements\nThe Jungle Swing is only available for participants aged 9 years and above\nBe aware that some areas might be crowded based on holiday periods\nCancellation policy applies','tour-packages/01KNA27CGZED69XPP7HA6069V0.png',1342000.00,1385000.00,1226000.00,1010000.00,1162000.00,'1 Day','Ubud, Bali','Ubud Tour',5.0,'fa-camera','Adventure',1,0,27,'2026-03-28 01:04:18','2026-04-03 16:18:38'),(5,1,1,'Balinese Culinary Journey & Village Life Experience','Taste tradition, learn the culture, and live like a local — all in one unforgettable day.','balinese-culinary-journey-village-life-experience','This hands-on experience invites you into the heart of Balinese life. Start the morning with a visit to a traditional market, explore the local spirituality at a village temple, and learn to cook authentic Balinese dishes using age-old recipes.\nEnd your journey with a warm village-style lunch that you prepare yourself — a true celebration of culture, community, and cuisine.','. Hands-on cultural experience with real Balinese locals\n2. Authentic cooking class led by expert village chefs\n3. Visit a functioning market — not a tourist show\n4. Suitable for all ages and dietary preferences\n5. A meaningful, immersive activity for foodies and cultural explorers alike','• Ubud Temple Visit - Discover the spiritual roots of Bali through a guided visit to a sacred local temple, learning about customs and offerings.\n• Traditional Market Tour - Experience the buzz of a local market, where you’ll pick out fresh herbs, spices, and ingredients with your cooking instructor.\n• Balinese Cooking Class - Learn how to prepare 5–7 traditional dishes, from satay to sambal, in a peaceful village kitchen.\n• Village-style lunch - Enjoy the fruits of your labor with a shared feast in an open-air dining space surrounded by nature','1. Hotel pick-up & drop-off by private car with English-speaking driver\n2. All entrance fees\n3. Full cooking class (ingredients, equipment, and recipe book included)\n4. Village-style lunch (you cook what you eat!)\n5. Mineral water','1. Personal shopping at the market\n2. Additional drinks or snacks not part of the class\n3. Gratuities',NULL,'Minimum 2 participants required per booking\nVegetarian/vegan/gluten-free options must be requested in advance\nModest clothing is recommended for temple visit (sarong provided if needed)\nTour may be rescheduled in case of religious ceremonies at the temple\nCancellation policy applies','tour-packages/01KN3HBBAKXMQYHPD3AN1GMBH0.png',1078500.00,1087500.00,938000.00,764000.00,938000.00,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Experience',1,1,48,'2026-03-28 04:37:05','2026-04-02 13:44:35'),(6,1,1,'Mount Batur Sunrise Trek & Hot Spring Escape','Climb, conquer, and unwind — experience Bali’s most magical sunrise from the summit of Mount Batur.','mount-batur-sunrise-trek-hot-spring-escape','Challenge yourself with one of Bali’s most iconic sunrise adventures at Mount Batur.\nTrek under the stars with a professional local guide, reach the summit in time for a breathtaking sunrise above the clouds, and enjoy a simple volcanic breakfast at the peak.\nAfter the hike, reward your body with a soothing soak at Toya Devasya Hot Spring overlooking Lake Batur and the surrounding mountains.\nThe perfect blend of adventure, nature, and relaxation for active travelers.','1. Witness a once-in-a-lifetime sunrise from 1,717 meters above sea level\n2. Guided trek with safe, scenic mountain trails\n3. Soothing hot spring experience after an active morning\n4. Suitable for adventure seekers and nature photographers\n5. Includes breakfast and entrance to a premium hot spring facility','1. Mount Batur Sunrise Trekking - Hike under a starlit sky with a local guide and reach the summit in time to witness the breathtaking sunrise over the volcano and surrounding caldera.\n2. Volcanic Breakfast at the Summit - Enjoy a simple yet memorable breakfast, often cooked using volcanic steam, as the sun rises above the clouds\n3. Toya Devasya Hot Spring - After the trek, soak in the natural thermal waters at a lakeside hot spring resort with stunning mountain views.','1. Round-trip hotel transfers (private vehicle, early morning pick-up)\n2. English-speaking local trekking guide\n3. Entrance fee to Mount Batur trekking area\n4. Admission to Toya Devasya Hot Spring (locker, towel, and welcome drink included)\n5. Mineral water.\n6. Private car 10 hours','1. Personal expenses at the hot spring (snacks, drinks, spa treatments)\n2. Trekking shoes or jacket\n3. Gratuities\n4. Over time ',NULL,'Minimum 2 participants required\nModerate fitness level required (2-hour uphill hike)\nWarm clothing and proper footwear recommended\nNot suitable for guests with heart or respiratory conditions\nCancellation policy applies.','tour-packages/01KNBZDZENSKZDR2D3AMYX1ANY.png',1237500.00,1237500.00,1015000.00,821000.00,1015000.00,'1 Day','Kintamani, Bali','Kintamani Tour',4.9,'fa-camera','Photography',1,0,28,'2026-03-28 04:45:29','2026-04-04 10:08:18'),(7,1,1,'East Bali Instagram Trail','Sacred beauty, majestic temples, and iconic photo moments in East Bali.','east-bali-instagram-trail','Discover the soul and splendor of Bali’s eastern highlands through our East Bali Instagram Trail, a curated journey to the island’s most photogenic and spiritually significant landmarks.\nBegin your day at the world-renowned Pura Lempuyang, home to the iconic “Gates of Heaven” where the towering Mount Agung provides a breathtaking backdrop.\nContinue to Pura Besakih, the mother temple of Bali, nestled on the slopes of the sacred volcano.\nThen, unwind amidst the peaceful water gardens of Tirta Gangga, a former royal palace with enchanting fountains and lotus-filled pools.\nThis tour blends spiritual discovery with stunning landscapes, making it perfect for photo lovers, cultural travelers, and anyone seeking a deeper Bali experience.','1. Iconic photo stop at the “Gates of Heaven”\n2. Visit Bali’s most sacred and largest temple\n3. Enjoy peaceful moments in a historic royal water palace\n4. Expert insights into Balinese Hindu culture\n5. A journey through the natural and spiritual heart of East Bali.','1. Pura Lempuyang (Gates of Heaven) – Take in one of Bali’s most famous photo spots with panoramic mountain views and a sense of divine peace\n2. Pura Besakih – Explore the largest and holiest temple complex in Bali, with layered terraces and centuries-old spiritual significance.\n3. Tirta Gangga – Stroll through serene water gardens filled with koi ponds, statues, and elegant Balinese architecture.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. Entrance tickets to all destinations\n3. Mineral water','1. Personal expenses (meals, drinks, snacks)\n2. Gratuities.',NULL,'Minimum 2 participants required\nWeather may affect visibility at Pura Lempuyang\nProper temple attire required (covered shoulders and knees)\nCancellation policy applies','tour-packages/01KMSDSQ6ZY3JCGQNDSQQ0SAYY.jpg',1102500.00,1102500.00,826000.00,631000.00,826000.00,'1 Day','East Bali','East Bali',4.9,'fa-camera','Photography',1,0,29,'2026-03-28 05:13:48','2026-04-02 13:44:35'),(8,1,1,'Kintamani Sacred Temple, Volcano View & Hidden Waterfall Escape','Discover Bali’s spiritual side and breathtaking nature','kintamani-sacred-temple-volcano-view-hidden-waterfall-escape','Discover the spiritual soul and natural beauty of Bali in one unforgettable day.\nBegin with the sacred holy spring temple of Tirta Empul, continue to the breathtaking Kintamani Viewpoint overlooking Mount Batur and Lake Batur, then finish with an adventurous visit to the magical Tukad Cepung Waterfall.\nA perfect balance of culture, mountain scenery, and hidden nature for first-time visitors and families.','1. Spiritual cleansing ritual at Tirta Empul\n2. Stunning mountain & lake view at Kintamani\n3. Hidden gem waterfall with magical sun rays\n4. Perfect balance of culture, nature & adventure\n5. Private & comfortable transportation','1. Tirta Empul Temple – Experience Balinese purification ritual (Melukat) at the holy spring temple.\n2. Kintamani Viewpoint – Panoramic view of Mount Batur & Lake Batur.\n3. Tukad Cepung Waterfall – Unique hidden waterfall inside a cave with sun rays shining through.','1. Hotel transfers (pick-up & drop-off)\n2. Private air-conditioned car\n3. English-speaking driver\n4. Entrance fees to all destinations\n5. Mineral water\n6. Private car 10 hours','1. Meals or snacks\n2. Ritual offerings or participation in purification ceremony\n3. Local guide inside the temple\n4. Gratuities\n5. Overtime',NULL,'Minimum 2 participants per booking\nModest attire is required for temple visit (sarong provided)\nRitual bathing at Tirta Empul is optional; observation is welcomed\nSuitable for guests of all ages\nCancellation policy applies','tour-packages/01KNBZ01HXB1RQ32JKPKG9WXBP.png',NULL,860000.00,780000.00,700000.00,NULL,'1 Day','Bali','Kintamani Tour',5.0,'fa-camera','Photography',1,0,30,'2026-03-29 09:40:56','2026-08-06 11:10:02'),(9,1,1,'Canggu Surf, Tanah Lot Temple & Finns Beach Club Sunset Tour','Ride the waves, explore Bali’s spiritual coast, and chill in Canggu’s hottest beach club.','canggu-surf-tanah-lot-temple-finns-beach-club-sunset-tour','Experience the best of Canggu with a perfect mix of surf, culture, and beach club lifestyle.\nStart with a beginner-friendly surf lesson at Batu Bolong Beach, continue to the iconic Tanah Lot Temple, and end your day at Finns Beach Club.\nEnjoy Bali’s trendiest coastal vibes with ocean views, sunset moments, and laid-back luxury.\nIdeal for couples, surfers, and lifestyle travelers seeking a stylish Bali day tour.','1. Experience the surf culture of Canggu with a guided lesson\n2. Explore Bali’s iconic coastal temple\n3. Relax at one of the most stylish beach clubs in Southeast Asia\n4. Ideal for young travelers, couples, and lifestyle seekers\n5. Great mix of adventure, culture, and luxury leisure','1. Batu Bolong Beach + Surfing - Ride beginner-friendly waves with certified instructors in the heart of Canggu’s surf scene.\n2. Tanah Lot Temple – Visit one of Bali’s most scenic spiritual landmarks, known for its dramatic ocean views.\n3. Finns Beach Club – Lounge at Canggu’s most famous beach club with oceanfront pools, cocktails, music, and unbeatable sunset vibes.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. 1-hour beginner surf lesson (board & rash guard included)\n3. Entrance ticket to Tanah Lot Temple\n4. Mineral water','1. Entry fee to Finns Beach Club\n2. Meals and beverages beyond included credit at Finns\n3. Locker/towel rental at beach or surf school\n4. Personal expenses (extra drinks, souvenirs, etc.)\n5. Gratuities',NULL,'Minimum 2 participants required\nSurfing activity subject to weather and tide conditions\nAdvance booking required for surfing and beach club access\nCancellation policy applies','tour-packages/01KPWX81TW310M3SYNYEZHZXP7.png',NULL,1125000.00,973000.00,796000.00,NULL,'1 Day','South Bali','South Bali',4.9,'fa-camera','Photography',1,1,44,'2026-03-29 09:57:56','2026-04-23 10:12:53'),(10,1,1,'South Bali Adventure: Watersport, GWK & Uluwatu Kecak Sunset Tour','A perfect blend of adventure, culture, and coastal beauty in South Bali’s iconic destinations.','south-bali-adventure-watersport-gwk-uluwatu-kecak-sunset-tour','Enjoy one of the best South Bali tours combining water sports, cultural landmarks, and iconic sunset views.\nStart with a fun banana boat ride at Tanjung Benoa, relax at Melasti Beach, explore the majestic GWK Cultural Park, and end your day with the famous Kecak Fire Dance at Uluwatu Temple.\nPerfect for couples, families, and travelers seeking a mix of adventure, culture, and scenic beauty.\nA complete Bali day tour covering the highlights of South Bali in one seamless experience.','1. Exciting water sports activity in the morning\n2. Stunning beach and cliffside photography opportunities\n3. Discover Balinese art and mythology at GWK\n4. Watch the famous Kecak & Fire Dance at Uluwatu during sunset\n5. Ideal for couples, families, and cultural explorers','1. Tanjung Benoa Watersport (Banana Boat Ride) – Begin with a splash! Experience the thrill of a banana boat ride at Bali’s popular water sport hub.\n2. Melasti Beach - Relax and take in the dramatic views at one of Bali’s most stunning white-sand beaches surrounded by limestone cliffs.\n3. Garuda Wisnu Kencana (GWK) Cultural Park – Explore the grand statue complex and learn about Balinese mythology and culture.\n4. Uluwatu Temple + Kecak Dance – Witness a mesmerizing fire dance set against a golden sunset at one of Bali’s most sacred sea temples.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. Banana boat ride at Tanjung Benoa (single ride/person)\n3. Entrance tickets to Melasti Beach, GWK, and Uluwatu Temple\n4. Kecak Dance ticket\n5. Mineral Water','1. Lunch or dinner\n2. Other water sport activities (jet ski, parasailing, etc.)\n3. Personal expenses (souvenirs, snacks, etc.)\n4. Guide inside the temple or cultural park (optional)\n5. Gratuities',NULL,'Minimum 2 participants required\nWear modest clothing for temple visits (sarong available for rent at the temple)\nWater sport activities are subject to weather and tide conditions\nNot recommended for pregnant women or those with certain medical conditions\nCancellation policy applies','tour-packages/01KPWWQFD44M62PB4C8DC3PT98.png',NULL,1012500.00,868000.00,700000.00,NULL,'1 Day','South Bali','South Bali',4.8,'fa-camera','Photography',1,0,31,'2026-03-29 10:03:47','2026-04-23 10:03:50'),(11,1,2,'Adventure Package 4D3N','4 Days of thrilling fun, nature, and cultural wonders — experience Bali’s adventurous side!','adventure-package-4d3n','Get ready for an unforgettable escape with our Adventure Package 4D3N, a perfectly curated itinerary that blends Bali’s most thrilling activities, iconic sights, and unforgettable experiences.\nWhether you\'re chasing the adrenaline of rafting and ATV rides or soaking in sunsets by the sea, this 4-day adventure will give you the perfect balance of fun, nature, and culture.\nStay in comfort, explore stunning beaches, race through jungle tracks, and embrace Bali’s spiritual and scenic soul — all in one seamless journey designed for the adventurous traveler.','1. Epic combo of water sports, cultural exploration, and jungle thrills\n2. Watch traditional Balinese Kecak Dance at a seaside cliff temple\n3. Ride through rivers and rice fields on an ATV\n4. Experience the beauty of Ubud’s natural landscape\n5. Stress-free with all transfers and activities arranged','Day 1 – Welcome to Bali!\n∙ Pick-up at Ngurah Rai International Airport\n∙ Hotel check-in\n∙ Sunset dinner or walk at Jimbaran Beach\n\nDay 2 – Beach Thrills & Cultural Gems\n∙ Tanjung Benoa – Enjoy a fun-filled Banana Boat ride\n∙ Relax at the dramatic Melasti Beach\n∙ Explore Garuda Wisnu Kencana (GWK) Cultural Park\n∙ Sunset at Uluwatu Temple + Traditional Kecak Fire Dance\n\nDay 3 – Jungle Adventure & Ubud Vibes\n∙ Morning ATV ride through villages and jungle trails\n∙ 2-hour White Water Rafting in scenic Ayung River\n∙ Instagram-worthy Ubud Swing experience\n∙ Visit to Tegalalang Rice Terrace\n\nDay 4 – Farewell Bali\n∙ Hotel check-out\n∙ Transfer to airport','Airport pick-up and drop-off\nPrivate AC vehicle with English-speaking driver\nAll activity entrance fees & equipment (ATV, rafting, banana boat, etc.)\nBottled water during tours','3 nights hotel accommodation\nLunch and dinner\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)',NULL,'Minimum 2 participants required\nActivities are weather dependent and may be adjusted for safety\n50% deposit required upon booking, full payment before arrival\nFree cancellation up to 7 days prior to arrival','tour-packages/01KMWHFNYXS5T34WW0ECJ5S2PA.jpg',NULL,3015000.00,2200000.00,1850000.00,NULL,'4 Day 3 Night','Bali',NULL,5.0,'fa-camera','Photography',1,1,42,'2026-03-29 10:15:57','2026-04-02 13:44:35'),(12,1,2,'Adventure Package 6D5N','6 Days of Action, Beauty & Culture – Bali’s Ultimate Adventure Journey','adventure-package-6d5n','Embark on an immersive 6-day adventure across Bali and beyond — where jungle trails, volcanic sunrises, sacred temples, and coastal wonders await.\nThe Adventure Package 6D5N is the perfect blend of action and serenity, combining thrilling land and sea excursions with moments of cultural discovery and tropical relaxation.\nWhether you\'re a first-timer or seasoned traveler, this all-in-one itinerary covers the best of Bali with comfort, convenience, and a spirit of exploration.','1. Full spectrum of Bali’s natural beauty and cultural magic\n2. Thrilling outdoor activities: Rafting, ATV, Banana Boat, Jeep Sunrise\n3. Journey to Nusa Penida’s dramatic coastline\n4. Soak in rejuvenating natural hot springs\n5. Ideal for adventurous couples, friends, or families','Day 1 – Arrival & Coastal Welcome\n∙ Pick-up at Ngurah Rai International Airport\n∙ Hotel check-in\n∙ Evening at Jimbaran Beach for a relaxed sunset or optional seafood dinner\n\nDay 2 – Watersports & Cliffside Temples\n∙ Morning Banana Boat ride at Tanjung Benoa\n∙ Explore the pristine shores of Melasti Beach\n∙ Cultural stop at Garuda Wisnu Kencana (GWK) Park\n∙ Uluwatu Temple visit with dramatic cliff views + Kecak Dance performance\n\nDay 3 – Jungle & River Adventure\n∙ Ride through natural trails on a powerful ATV\n∙ Thrilling White Water Rafting (2 hours) along the Ayung River\n∙ Swing over lush valleys at the Ubud Swing\n∙ Visit the scenic Tegalalang Rice Terrace\n\nDay 4 – Island Discovery: Nusa Penida\n∙ Speedboat to Nusa Penida (West Side)\n∙ Visit to iconic Kelingking Beach, Broken Beach, Angel’s Billabong\n∙ Chill and swim at Crystal Bay\n∙ Return to mainland Bali\n\nDay 5 – Volcanic Sunrise & Hot Springs\n∙ Early morning 4WD Jeep Sunrise Tour at Mount Batur\n∙ Lunch with volcano view in Kintamani\n∙ Relax and unwind in a natural Hot Spring by the lake\n\nDay 6 – Departure Day\n∙ Hotel check-out\n∙ Airport drop-off by private transfer\n','Airport pick-up and drop-off\nPrivate AC vehicle with English-speaking driver\nReturn fast boat to Nusa Penida + island transportation\nEntrance fees and equipment for all activities\nBottled water during tours','5 nights hotel accommodation\nLunch and dinner\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)',NULL,'Minimum 2 participants required\nActivities are weather dependent and may be adjusted for safety\n50% deposit required upon booking, full payment before arrival\nFree cancellation up to 7 days prior to arrival','tour-packages/01KMWHQH3BTV2AEY998DFX951P.jpg',NULL,5500000.00,4000000.00,3500000.00,NULL,'6 Day 5 Night','Bali',NULL,5.0,'fa-camera','Photography',1,1,43,'2026-03-29 10:20:14','2026-04-02 13:44:35'),(13,1,1,'Penida Harmony (East and west mix)','The best of both worlds — explore the iconic wonders of East and West Nusa Penida in one harmonious journey.','Penida Mix – East & West Highlights','Explore the best of East and West Nusa Penida in one full-day trip.\nVisit famous cliffs, stunning white sand beaches, and the island’s most scenic viewpoints.\nPerfect for travelers who want to see all the top spots in one easy and well-balanced tour.','1. Experience five of the most iconic destinations in one day\n2. Balanced itinerary of photo spots, adventure, and relaxation\n3. Stunning cliffside viewpoints and white sand beaches\n4. Ideal for explorers with limited time who want to see it all\n5. Seamless and private tour with expert local guidance.','1. Kelingking Beach\n2. Angel’s Billabong\n3. Broken beach\n4. Diamond beach\n5. Tree House ','1. Return fast boat ticket (Bali - Nusa Penida)\n2. All entrance fees\n3. Hotel Transfers\n4. Mineral water\n5. Lunch\n6. English speaking driver\n7. Private air-conditioned vehicle','1. Personal Expenses\n2. Any activities at destinations\n',NULL,'Maximum 5 persons per car (include driver / guide)\nPlease contact us prior to your booking date for smooth arrangements\nBring sunscreen and some cash for personal expenses\nNot wheelchair accessible\nThis experience requires good weather. If it’s canceled due to poor weather, you’ll be offered a different date or a full refund\nContact us for pickup outside the designated areas\nBe aware that some areas might be crowded based on holiday periods\n','tour-packages/01KN29MP1T9FG28XEMWEM718SR.jpg',NULL,1440000.00,1395000.00,1275000.00,NULL,'1 Day','Bali','Island Tour',5.0,'fa-camera','Photography',1,0,32,'2026-03-31 06:43:12','2026-08-04 08:36:13'),(14,1,1,'Nusa Lembongan Island Escape','A laid-back island getaway filled with natural beauty, cliffside drama, and coastal charm.','nusa-lembongan-island-escape','Escape to the peaceful charm of Nusa Lembongan on a relaxing island day tour filled with stunning coastal views, dramatic cliffs, and crystal-clear waters.\nVisit the island’s most iconic spots including Dream Beach, Devil’s Tear, and the famous Yellow Bridge.\nPerfect for couples, families, or anyone looking for a calm tropical getaway away from the crowds.\nEnjoy a smooth private journey with fast boat transfers, lunch, and comfortable hotel pick-up included','1. Short boat ride from Bali to a laid-back island paradise\n2. Perfect for relaxation, photography, and easy exploration\n3. Great mix of nature, coastal beauty, and iconic island landmarks\n4. Less crowded than Nusa Penida, ideal for a calmer experience\n5. Free time to explore or enjoy local cafes near the beach','1. Dream Beach – A beautiful white-sand beach with stunning turquoise water, perfect for    relaxing and taking photos\n\n2. Devil’s Tear – A dramatic cliffside viewpoint where powerful waves crash against the rocks\n\n3. Yellow Bridge – The famous yellow suspension bridge connecting Nusa  Lembongan and Nusa Ceningan','1. Return fast boat ticket (Bali - Nusa Lembongan)\n2. All entrance fees\n3. Hotel Transfers\n4. Mineral water\n5. Lunch\n6. English speaking driver\n7. Private air-conditioned vehicle','1. Personal Expenses\n2. Any activities at destinations',NULL,'Maximum 5 persons per car (include driver / guide)\nPlease contact us prior to your booking date for smooth arrangements\nBring sunscreen and some cash for personal expenses\nNot wheelchair accessible\nThis experience requires good weather. If it’s canceled due to poor weather, you’ll be offered a different date or a full refund\nContact us for pickup outside the designated areas\nBe aware that some areas might be crowded based on holiday periods','tour-packages/01KN2G40BT2RN958VWV5FP2SP2.jpg',NULL,1012500.00,924000.00,780000.00,NULL,'1 Day','Bali','Island Tour',5.0,'fa-earth-oceania','Island',1,0,33,'2026-03-31 06:48:44','2026-04-02 13:44:35'),(15,1,1,'Bali Spiritual Purification & Healing Journey','Cleanse your soul, awaken your spirit, and reconnect with inner peace.','bali-spiritual-purification-healing-journey','Reconnect with Bali’s sacred energy through a peaceful day of temple visits, holy spring rituals, and serene landscapes.\nExperience the traditional melukat purification ceremony, explore ancient temples, and end with the calming beauty of Tegalalang Rice Terrace.\nPerfect for travelers seeking healing, clarity, and a deeper spiritual connection with Bali.','1. Experience a traditional Balinese water purification ritual (Melukat)\n2. Visit 3 spiritual temples in one enlightening journey\n3. Ideal for those seeking emotional balance, clarity, and calm\n4. Led by a knowledgeable driver-guide with insights into Balinese Hinduism\n5. Optional prayer session and offerings available upon request','1. Tirta Empul Temple - Participate in a sacred melukat purification ritual at this 1,000-year-old water temple, where locals come to cleanse mind, body, and spirit.\n2. Gunung Kawi Temple - Explore this stunning 11th-century temple complex carved into rock cliffs, accessible through lush rice terraces and sacred paths\n3. Sebatu Holy Spring - A peaceful and less-crowded water temple known for its serene atmosphere and spiritually charged waters\n4. Tegalalang Rice Terrace - End your journey with a tranquil walk and scenic break among Bali’s most iconic rice fields.','1. Hotel pick-up & drop-off by private car with English-speaking driver\n2. Entrance tickets to Tirta Empul, Gunung Kawi, Sebatu Temple, and Tegalalang\n3. Ritual offerings (canang, flowers, incense) for purification ceremony\n4. Sarong and sash rental for temple visits\n5. Mineral water\n6. Private car 10 hours ','1. Local guide inside temples\n2. Lunch\n3. Personal offerings for private blessings\n4. Gratuities\n5. Overtime charge',NULL,'Minimum 2 participants required per booking\nModest clothing is required (shoulders and knees covered)\nRespectful behavior inside temple premises is mandatory\nRitual participation is optional; observation is welcome\nTour may be adjusted on special Hindu ceremony days\nCancellation policy applies','tour-packages/01KN4XVMAS8M6V302R1BRCCEJC.png',NULL,968000.00,903000.00,838000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,34,'2026-03-31 06:57:44','2026-04-02 13:44:35'),(16,1,1,'Bali Spiritual & Nature Healing Escape','A meaningful experience of purification, ancient temples, and serene natural beauty around Ubud','bali-spiritual-nature-healing-escape','Discover the deeper essence of Bali through a sacred purification ritual, visits to ancient temple heritage, and peaceful natural landscapes hidden within lush valleys.','1. A calming blend of spirituality, history, and nature\n2. Participate in a traditional Balinese purification ceremony (Melukat)\n3. Visit one of Bali’s oldest temple complexes carved into rock cliffs\n4. Enjoy tranquil jungle scenery and a hidden waterfall\n5. Experience a more peaceful side of Ubud away from crowded tourist spots\n','1. Melukat at Beji Griya Waterfall Temple – Experience a sacred Balinese water purification ritual at a hidden waterfall temple, guided by local tradition.\n2. Gunung Kawi Temple - Visit one of Bali’s oldest temple complexes, carved into towering rock cliffs and surrounded by lush river valleys.\n3. Tibumana Waterfall - A serene and scenic waterfall tucked in the jungle, perfect for a peaceful nature stop after the purification ritual.','1. Hotel pickup and drop-off\n2. Entrance tickets to all listed destinations\n3. Melukat entrance and offerings\n4. Mineral water\n5. Private car 10 hours \n6. English speaking driver\n7. Private air-conditioned vehicle','1. Personal Expenses & gratuities\n2. Lunch and personal snacks\n3. Overtime charge',NULL,'Minimum 2 participants required per booking\nModest dress code required for temple visits (knees and shoulders covered)\nTour itinerary may be adjusted based on weather or local ceremonies\nCancellation policy applies','tour-packages/01KN4V9X09PA7DP0PNYJM9JGTR.png',NULL,960000.00,720000.00,640000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,35,'2026-03-31 07:00:05','2026-04-02 13:44:35'),(17,1,1,'Ubud ATV & Ayung Rafting Experience','An adrenaline-packed day combining Bali’s most exciting activities with a touch of culture','ubud-atv-ayung-rafting-experience','This tour is perfect for adventure seekers — ride through jungles and muddy tracks on an ATV, conquer the rapids with Ayung rafting, enjoy a delicious Indonesian lunch, and end the day with a relaxing visit to a coffee plantation for a traditional tasting experience.','1. Action-packed combo: ATV + rafting in one day\n2. Scenic jungle, rice fields, and river tracks for ATV ride\n3. Fun white-water rafting suitable for beginners and adventure lovers\n4. Delicious  lunch included\n5. Visit a local coffee plantation and taste Bali’s unique coffee','1. ATV Adventure – 1.5 hours of thrilling ride through rice fields, rivers, and jungle tracks.\n2. Ayung Rafting – 2 hours of excitement along Bali’s beautiful river rapids.\n3. Lunch – Recharge with a delicious Indonesian food\n4. Coffee Plantation – Learn about Bali’s famous coffee and taste various local blends.','1. Hotel transfers (pick-up & drop-off)\n2. Private air-conditioned car\n3. English-speaking driver\n4. ATV activity ( 1 - 1.5 hours)\n5. Ayung Rafting (2 hours)\n6. Safety equipment (helmets, life jackets)\n7. Lunch indonesia foods\n8. Entrance to coffee plantation + tasting\n9. Mineral water','1. Personal expenses (souvenirs, extra drinks, etc.)\n2. Tips for driver/guide (optional)',NULL,'Minimum 2 participants required per booking\nPlease contact us prior to your booking date for smooth arrangements\nBe aware that some areas might be crowded based on holiday periods\nCancellation policy applies','tour-packages/01KP183DH7RSEQZ5R8Z8EWYHX7.png',NULL,1095000.00,950000.00,850000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,1,36,'2026-03-31 07:03:19','2026-08-04 08:56:15'),(18,1,1,'Ubud Swing, Sky Bike & Waterfall Experience','A perfect mix of adrenaline, Instagrammable spots, and relaxation','ubud-swing-sky-bike-waterfall-experience','Enjoy the perfect Ubud day trip filled with adventure, scenic views, and relaxing nature.\nFeel the thrill of Sky Bike, Flying Fox, and the iconic Alas Harum Swing, then refresh at the beautiful Kanto Lampo Waterfall.\nComplete your journey with a relaxing Balinese coffee plantation tasting for the perfect Ubud escape.','1. Test your courage with Sky Bike & Flying Fox\n2. Iconic Ubud Swing with scenic rice terrace backdrop\n3. Discover the hidden beauty of Kanto Lampo Waterfall\n4. Experience Bali’s coffee culture with authentic tasting\n5. Private car & driver for comfort and flexibility','• Sky Bike at Alas Harum - Ride a unique bike suspended in the air, offering amazing views of the rice terraces and surrounding nature.\n• Flying Fox at Alas Harum - Soar through the air on a Flying Fox zipline for an adrenaline rush above Bali\'s lush landscapes.\n• Swing at Alas Harum - Experience the ultimate Bali swing, floating above picturesque views of the jungle and rice fields.\n• Kanto Lampo Watefall - Explore this hidden waterfall with its beautiful cascading waters and serene pool.\n• Coffee Plantation - Learn about Bali\'s traditional coffee production, including the famous Luwak coffee, and enjoy a tasting session.','1. Hotel transfers (pick-up & drop-off)\n2. Private air-conditioned car\n3. English-speaking driver\n4. Tickets for Sky Bike, Flying Fox & Swing (Alas Harum)\n5. Entrance fee Kanto Lampo Waterfall\n6. Entrance to coffee plantation + tasting\n7. Mineral water\n8. Private car 10 hours','1. Lunch or meals\n2. Personal expenses (souvenirs, snacks, extra drinks, etc.)\n3. Tips for driver/guide (optional)\n4. Overtime charge',NULL,'Minimum 2 participants required per booking\nPlease contact us prior to your booking date for smooth arrangements\nBe aware that some areas might be crowded based on holiday periods\nCancellation policy applies','tour-packages/01KN4WVYFC4KFWHS03R4EHN7YQ.png',NULL,1095000.00,896000.00,758000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',5.0,'fa-camera','Photography',1,1,47,'2026-03-31 07:05:52','2026-04-29 02:17:17'),(19,1,1,'Ubud Jungle Cart, Swing & Waterfall Experience','Experience the thrill of Ubud’s top adventure activities combined with breathtaking jungle scenery and iconic photo spots.','ubud-jungle-cart-swing-waterfall-experience','Discover the perfect Ubud adventure with jungle thrills, iconic swing views, and Bali’s famous waterfall scenery.\nRide the exciting Jungle Cart, soar above rice terraces at Uma Ceking Swing, and unwind at the refreshing Tegenungan Waterfall.\nA perfect day trip for couples, families, and nature lovers seeking adventure and Instagram-worthy moments.','1. Perfect for nature lovers and adventure seekers\n2. Jungle Cart ride through scenic tropical tracks\n3. Swing at Uma Ceking with panoramic rice terrace views\n4. Refreshing visit to Tegenungan Waterfall\n5. Private driver & comfortable air-conditioned vehicle\n6. Great for couples, families, and big groups','• Jungle Cart\nEnjoy a thrilling off-road ride on tropical jungle tracks — fun, fast, and perfect for adventure photographers.\n• Swing at Uma Ceking\nFly above the stunning Tegallalang Rice Terrace with a panoramic jungle backdrop. One of Ubud’s most iconic Instagram photo spots.\n• Tegenungan Waterfall\nA scenic and powerful waterfall where you can relax, explore, and enjoy fresh natural views.','1. All entrance fees\n2. Jungle Cart ticket\n3. Uma Ceking Swing ticket\n4. Private air-conditioned vehicle\n5. Private car 10 hours\n6. Hotel transfers\n7. English-speaking driver','1. Lunch\n2. Personal expenses\n3. Extra activities not mentioned\n4. Professional photographer services (optional)\n5. Overtime charge',NULL,'1. Please contact us ahead of your tour date for smooth arrangements\n2. Bring sunscreen, comfortable shoes, and some cash\n3. Not wheelchair accessible\n4. This experience may be affected by weather conditions; if canceled due to heavy rain, you’ll be offered a different date or full refund\n5. Contact us for pickup outside designated areas\n6. Some locations may be crowded during weekends or holidays','tour-packages/01KN4XQ61161HAXBFAY7MKDQY5.png',NULL,1265000.00,1000000.00,900000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',5.0,'fa-camera','Photography',1,0,37,'2026-03-31 07:10:44','2026-04-02 13:44:35'),(20,1,1,'Ubud UTV Buggy, Rafting & Rice Terrace Experience','A full day of adrenaline, nature, and stunning scenery in the heart of Ubud.','ubud-utv-buggy-rafting-rice-terrace-experience','Enjoy the ultimate Ubud adventure with a thrilling UTV Buggy ride, scenic Ayung River rafting, and the breathtaking beauty of Tegalalang Rice Terrace.\nThis full-day experience is perfect for couples, families, and adventure lovers looking for Bali’s best mix of adrenaline and nature.','1. 1-hour UTV Buggy Ride with fun jungle & mud tracks\n2. Rafting at the stunning Ayung River\n3. Iconic views at Tegalalang Rice Terrace\n4. All safety gear and facilities included\n5. Private, comfortable, air-conditioned vehicle','1. UTV Buggy Ride (1 Hour)\nEnjoy a fun and adventurous ride through Ubud’s natural surroundings, including jungle paths, mud areas, tunnels, rice fields, and a short circuit section. Guided by a professional instructor with complete safety gear.\n2. Ayung River Rafting\nBali’s most scenic rafting route — enjoy jungle cliffs, fun rapids, and the iconic stone carvings along the river.\n3. Tegalalang Rice Terrace\nA stunning terraced landscape with beautiful viewpoints and photo spots.','1. All entrance fees\n2. UTV Buggy Ride (1 hour)\n3. Ayung River Rafting\n4. Tegalalang Rice Terrace entry\n5. Lunch\n6. Safety gear\n7. Towel, soap & shower facilities\n8. Professional instructor\n9. Insurance\n10. Private air-conditioned vehicle\n11. Hotel transfer\n12. English-speaking driver\n13. Private car 10 hours','1. Personal expenses\n2. Extra activities not listed\n3. Optional photo/video services\n4. Overtime charge',NULL,'Please confirm your booking date in advance\nBring sunscreen, dry clothes, and waterproof covers for devices\nNot wheelchair accessible\nWeather may affect rafting conditions; alternative date or refund will be provided if needed\nPickup outside designated areas available on request','tour-packages/01KN6S5JK53WX6Q8MYBY51TZSX.png',NULL,1400000.00,1250000.00,1020000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',5.0,'fa-camera','Photography',1,0,38,'2026-03-31 07:18:05','2026-06-19 18:37:05'),(21,1,1,'Ubud River Tubing, ATV & Coffee Experience','A fun and refreshing day of adventure in Ubud’s natural landscape.','ubud-river-tubing-atv-coffee-experience','Discover the perfect Ubud adventure with a refreshing river tubing experience, thrilling ATV ride, and relaxing Balinese coffee plantation visit.\nThis full-day trip is ideal for couples, families, and adventure lovers looking for the best mix of fun, nature, and local culture.','1. River Tubing through natural forest streams\n2. Muddy and fun ATV Ride adventure\n3. Coffee tasting at a traditional Balinese plantation\n4. Private car with English-speaking driver\n5. Great mix of adventure and relaxation','1. River Tubing\nEnjoy a refreshing tubing experience along a beautiful natural river with small rapids, quiet streams, and scenic jungle surroundings.\n2. ATV Ride\nRide through muddy tracks, jungle trails, rice fields, and challenging terrain for a fun, adrenaline-filled adventure.\n3. Coffee Plantation\nLearn how Bali’s traditional coffee is made and enjoy complimentary tastings of various local coffees and teas. Luwak coffee is optional.','1. River Tubing\n2. ATV Ride\n3. Lunch\n4. Safety gear\n5. Towel & shower facilities\n6. Professional instructor\n7. Insurance\n8. Private air-conditioned vehicle\n9. Hotel transfers\n10. English-speaking driver\n11. Private car 10 hours','1. Personal expenses\n2. Luwak coffee tasting (optional)\n3. Photo/video services\n4. Overtime charge',NULL,'Please confirm your booking date in advance\nBring sunscreen, extra clothes, and waterproof protection for devices\nNot wheelchair accessible\nActivities may be affected by weather\nPickup outside designated areas available on request\n\n','tour-packages/01KN6VG7A83V68BBPENSSHA5F2.png',NULL,1120000.00,950000.00,780000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',5.0,'fa-camera','Photography',1,0,39,'2026-03-31 07:21:22','2026-08-04 08:53:31'),(22,1,1,'Ubud Yoga, Monkey Forest & Waterfall Retreat','Reconnect your body, mind, and soul in the natural sanctuary of Ubud.','ubud-yoga-monkey-forest-waterfall-retreat','Reconnect your body and mind with a peaceful Ubud wellness journey.\nEnjoy a relaxing 1-hour yoga session, explore the sacred Monkey Forest Sanctuary, and refresh at the beautiful Tegenungan Waterfall.\nPerfect for solo travelers, couples, and anyone seeking a mindful Bali escape.','1. A balanced mix of physical, spiritual, and natural wellness\n2. Ideal for beginners and experienced yogis alike\n3. Rejuvenating escape in Bali’s cultural heart\n4. Includes time for gentle nature walks and mindful exploration\n5. A thoughtful gift for solo travelers or couples seeking peaceful connection','1. Yoga Session in Ubud - Start your day with a peaceful yoga practice led by a certified instructor in a serene open-air studio surrounded by tropical greenery. Suitable for all levels.\n2. Monkey Forest - Connect with nature and spirituality in this sacred forest sanctuary where monkeys roam freely among ancient temples and towering trees.\n3. Tegenungan Waterfall - A powerful and refreshing natural waterfall set in lush jungle, offering the perfect place to pause, reflect, and take in Bali’s beauty','1. 1-hour group yoga session with instructor and mat provided\n2. Entrance fees to Monkey Forest and Tegenungan Waterfall\n3. Mineral water\n4. English speaking driver\n5. Private air-conditioned vehicle\n6. Private car 10 hours','1. Meals\n2. Personal shopping or expenses\n3. Extra wellness activities (massage, spa, etc.)\n4. Gratuities\n5. Overtime charge',NULL,'Minimum 2 participants required per booking\nItinerary may adjust depending on yoga studio availability or weather\nCancellation policy applies\nComfortable yoga/active wear recommended','tour-packages/01KN6W08QZ94K2J11YE5JA5S7B.png',NULL,855000.00,721000.00,563000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,40,'2026-03-31 07:23:43','2026-04-02 13:44:35'),(23,1,1,'Bali Safari, Bird Park & Coffee Experience','A day of discovery, wonder, and wild encounters in Bali\'s lush landscapes.','bali-safari-bird-park-coffee-experience','Enjoy a fun-filled Bali day with exotic wildlife, colorful tropical birds, and local coffee culture.\nMeet amazing animals at Bali Safari Park, explore the beautiful Bali Bird Park, and finish with a relaxing coffee plantation tasting.\nPerfect for families, kids, couples, and nature lovers.','1. Fun and educational experiences for all ages\n2. Get up close with exotic animals and rare birds\n3. Easy-paced tour with interactive shows and nature walks\n4. Great balance of adventure and scenic relaxation\n5. Learn about Bali’s traditional coffee production and taste Luwak coffee','1. Bali Safari & Marine Park - Bali’s premier wildlife park, home to over 100 species including endangered animals like the Sumatran tiger, white rhino, and Komodo dragon. Enjoy a thrilling safari ride, animal shows, and up-close wildlife encounters.\n2. Bali Bird Park - Walk through aviaries filled with over 1,000 birds from Indonesia and around the world. A paradise for birdwatchers and photographers!\n3. Coffee Plantation – Discover Bali’s famous coffee culture, including the renowned Luwak coffee, straight from the source.','1. Adult entrance tickets to Bali Safari & Marine Park and Bali Bird Park\n2. Visit to Coffee Plantation\n3. Mineral water\n4. English speaking driver\n5. Private air-conditioned vehicle','1. Lunch\n2. Entrance tickets for children\n∙ Bali Safari child ticket : IDR 250,000\n∙ Bali Bird Park child ticket : IDR 385,000\n3. Animal feeding or special animal encounters (optional at own expense)\n4. Souvenirs and personal expenses\n5. Gratuities',NULL,'Minimum 2 participants required per booking\nAdvance booking is required, especially during weekends/holidays\nPrices may vary during peak seasons or special park events\nCancellation policy applies\nNotes :\nPrices listed are for adults. Children’s entrance tickets are charged separately as add-ons.','tour-packages/01KN6WGBVY5AE3B07VAV41K8G1.png',NULL,1676000.00,1564000.00,1452000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,41,'2026-03-31 07:29:14','2026-04-02 13:44:35'),(24,1,1,'Ubud Swing, Monkey Forest & Waterfall Experience','A perfect blend of culture, nature, and adventure in the heart of Bali','ubud-swing-monkey-forest-waterfall-experience','Discover the classic beauty of Ubud with a perfect mix of scenic adventure, wildlife, and tropical nature.\nEnjoy the iconic Alas Harum Swing, visit the sacred Ubud Monkey Forest, and refresh at the stunning Tegenungan Waterfall.\nPerfect for couples, families, and travelers who want Bali’s most Instagram-worthy Ubud highlights.','1. Experience the thrill of the Bali Swing at Alas Harum\n2. Meet the monkeys in their sacred jungle habitat\n3. Capture amazing photos at the famous Tegenungan Waterfall\n4. Private tour with flexible schedule and English-speaking driver\n5. Comfortable air-conditioned car with hotel transfers','1. Alas Harum Swing – Soar high above the rice terraces on Bali’s famous swing.\n2. Monkey Forest Ubud – Explore the sacred sanctuary home to hundreds of playful long-tailed macaques.\n3. Tegenungan Waterfall – Refresh yourself and capture stunning photos at one of Bali’s most scenic waterfalls.','1. Hotel pickup and drop-off\n2. All entrance fees\n3. Mineral water\n4. English speaking driver\n5. Private air-conditioned vehicle\n6. Private car 10 hours','1. Personal Expenses\n2. Gratuities\n3. Lunch and personal snacks\n4. Overtime charge\n',NULL,'Minimum 2 participants required per booking\nPlease contact us prior to your booking date for smooth arrangements\nThe Jungle Swing is only available for participants aged 9 years and above','tour-packages/01KN6WWCCKTY1Y2PF9V1E67PMD.png',NULL,937500.00,798000.00,635000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,26,'2026-03-31 07:34:25','2026-04-02 13:44:35'),(25,1,1,'Ubud Waterfall, Swing & Cretya Jungle Club Experience','A perfect blend of nature, iconic photo spots, and a relaxing jungle club atmosphere in the heart of Ubud.','ubud-waterfall-swing-cretya-jungle-club-experience','Discover the perfect Ubud day escape with hidden waterfalls, iconic rice terrace swings, and a relaxing jungle club vibe.\nVisit the peaceful Ulu Petanu Waterfall, enjoy the famous Alas Harum Swing, and unwind at the stylish Cretya Ubud Jungle Club.\nPerfect for couples, girls trips, and travelers looking for Bali’s most Instagrammable Ubud experience.','1. Visit the hidden Ulu Petanu Waterfall\n2. Famous Alas Harum Swing over rice terraces\n3. Relax at Cretya Ubud Jungle Club\n4. Stunning jungle & rice field views all day\n5. Private, comfortable, air-conditioned vehicle','1. Ulu Petanu Waterfall\nA peaceful and scenic waterfall surrounded by lush jungle. Walk down to the natural pool, enjoy the fresh air, and take beautiful nature photos away from heavy crowds.\n2. Swing at Alas Harum\nExperience the iconic Bali swing overlooking rice terraces. The area also offers multiple photo spots, bird nests, and beautiful landscape views.\n3. Cretya Ubud Jungle Club\nA stylish jungle club with multi-level infinity pools overlooking rice fields. Perfect to relax, swim, take photos, and enjoy drinks or food in a stunning setting.','1. All entrance fees\n2. Swing experience at Alas Harum\n3. Ulu Petanu Waterfall entry\n4. Cretya Ubud entry\n5. Private air-conditioned vehicle\n6. Hotel pickup & drop-off\n7. English-speaking driver\n8. Private car 10 hours ','1. Food & beverages at Cretya\n2. Personal expenses\n3. Optional photo/video services\n4. Towel & locker rental (if required)\n5. Overtime charge',NULL,'1. Please confirm your booking date in advance\n2. Bring sunscreen, dry clothes, and waterproof covers for devices\n3. Not wheelchair accessible\n4. Weather may affect rafting conditions; alternative date or refund will be provided if needed\n\n','tour-packages/01KN6XQW9477V3K0FH71F84X74.png',NULL,1035000.00,790000.00,700000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,14,'2026-03-31 07:37:19','2026-04-02 13:44:35'),(26,1,1,'Ubud Silver Class, Palace & Waterfall Experience','Discover the artistic heart of Bali through culture, craftsmanship, and nature.','ubud-silver-class-palace-waterfall-experience','Discover the artistic soul of Ubud through hands-on craftsmanship, royal heritage, local market charm, and tropical nature.\nCreate your own jewelry in a Balinese silver making class, visit the iconic Ubud Royal Palace, explore the lively Traditional Market, and refresh at the beautiful Kanto Lampo Waterfall.\nPerfect for couples, families, and travelers who love culture, art, and scenic Bali experiences.','1. Join a traditional Silver Making Class in Ubud\n2. Visit the historic Ubud Royal Palace\n3. Explore the lively Ubud Traditional Market\n4. Swim & take photos at Kanto Lampo Waterfall\n5. Private, comfortable air-conditioned vehicle','1. Silver Making Class (Ubud Area)\nExperience Balinese craftsmanship by creating your own silver jewelry piece guided by local artisans. A unique cultural activity and memorable souvenir to take home.\n2. Ubud Royal Palace\nA historic palace located in the center of Ubud, known for its traditional Balinese architecture and cultural significance.\n3. Ubud Traditional Market\nA vibrant local market where you can see daily Balinese life and shop for handicrafts, textiles, and souvenirs.\n4. Kanto Lampo Waterfall\nA beautiful tiered waterfall famous for its rock formations and photogenic cascades. A short walk leads you to the waterfall area where you can swim and take stunning photos.','1. Silver making class experience\n2. Silver material (basic amount)\n3. All entrance fees\n4. Private air-conditioned vehicle\n5. Hotel pickup & drop-off\n6. English-speaking driver\n7. Parking & fuel\n8. Private car 10 hours','1. Additional silver material (if design exceeds basic amount)\n2. Lunch\n3. Personal expenses\n4. Optional photo/video services\n5. Overtime charge',NULL,'1. Advance booking required\n2. Wear comfortable footwear (stairs at waterfall)\n3. Bring change of clothes & towel for waterfall visit\n4. Not wheelchair accessible\n5. Weather conditions may affect waterfall safety\n6. Pickup outside main areas available upon request','tour-packages/01KN91KZHHY4YREWGP4FF48K53.png',NULL,1470000.00,1350000.00,1229999.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,2,'2026-03-31 07:40:25','2026-05-04 06:42:25'),(27,1,1,'Ubud Classic VW Ride, Ayung Rafting & Rice Terrace Experience','A perfect combination of adrenaline, scenic beauty, and unique Bali experiences.','ubud-classic-vw-ride-ayung-rafting-rice-terrace-experience','Enjoy the perfect Ubud adventure with thrilling river rafting, vintage countryside vibes, and Bali’s most iconic rice terrace views.\nExperience the scenic Ayung River rafting, cruise through Ubud in a stylish classic Volkswagen ride, and capture unforgettable moments at Tegalalang Rice Terrace.\nPerfect for couples, families, and travelers who want a unique mix of adventure and aesthetic Bali experiences.','1. Thrilling Ayung River Rafting adventure\n2. Ride a classic Volkswagen (VW) car through Ubud\n3. Visit the iconic Tegalalang Rice Terrace\n4. Jungle views, river scenery, and rice field landscapes\n5. Private, comfortable air-conditioned vehicle','1. Ayung River Rafting\nExperience Bali’s most scenic rafting route featuring jungle cliffs, waterfalls, stone carvings along the river, and fun rapids suitable for beginners.\n2. Classic VW Car Ride (1 Hour)\nEnjoy a stylish ride in a vintage Volkswagen car around Ubud’s scenic countryside — perfect for photos and a unique Bali experience.\n3. Tegalalang Rice Terrace\nOne of Bali’s most famous rice terraces with beautiful viewpoints and photo spots overlooking layered green fields.','1. Ayung River rafting experience\n2. Professional rafting guide\n3. Safety equipment (helmet & life jacket)\n4. Shower & towel facilities\n5. Lunch\n6. Classic VW car rental (1 hour)\n7. Tegalalang Rice Terrace entrance\n8. Private air-conditioned vehicle\n9. Hotel pickup & drop-off\n10. English-speaking driver\n11. Private car 10 hours','1. Personal expenses\n2. Optional swing or extra activities at Tegalalang\n3. Optional photo/video services\n4. Tips & gratuities\n5. Overtime charge',NULL,'1. Advance booking required\n2. Participants must be in good physical condition\n3. Not recommended for pregnant women or guests with serious medical conditions\n4. Bring change of clothes & sunscreen\n5. Wear comfortable footwear\n6. Weather conditions may affect rafting operations','tour-packages/01KNA0XWX4TJJRT4QXJG1D3NF4.png',NULL,1100000.00,840000.00,750000.00,NULL,'1 Day','Ubud, Bali','Ubud Tour',4.9,'fa-camera','Photography',1,0,3,'2026-03-31 07:43:13','2026-04-03 15:55:59'),(28,1,1,'Mount Batur Volcano Jeep Sunrise Escape','A thrilling off-road journey through volcanic landscapes and natural beauty — no hiking required.','mount-batur-volcano-jeep-sunrise-escape','Experience the magic of Mount Batur on a thrilling sunrise jeep adventure through Bali’s most iconic volcanic landscape.\nTravel across dramatic black lava fields and volcanic sand trails in a powerful 4WD, with no trekking required.\nWitness breathtaking sunrise views from the mountain viewpoint, then continue with a scenic lunch in Kintamani’s cool highlands.\nComplete the journey with pure relaxation at Toya Devasya Hot Spring overlooking the lake and mountains.','1. Jeep sunrise adventure — ideal for all ages & fitness levels\n2. Explore lava formations and volcanic scenery without hiking\n3. Delicious lunch in the mountains with volcano views\n4. Relaxing hot spring experience to complete your day\n5. Perfect for couples, families, and photographers','1. 4WD Jeep Sunrise Adventure - Ride across volcanic terrain in a custom 4x4 Jeep and witness a golden sunrise over Mount Batur and Lake Batur — no trekking required!\n2. Black Lava & Black Sand Exploration – Journey through surreal landscapes formed by ancient eruptions, ideal for stunning photos and video.\n3. Lunch in Kintamani Highlands – Savor a freshly prepared local meal with panoramic views of the volcano.\n4. Toya Devasya Hot Spring – End your adventure with a rejuvenating soak in natural thermal waters surrounded by nature.','1. Hotel pickup and drop-off with air-conditioned vehicle\n2. 4WD Jeep with driver and local guide\n3. Entrance fees to sunrise viewpoint\n4. Admission to Toya Devasya Hot Spring (locker, towel, welcome drink)\n5. Lunch at a local restaurant in Kintamani\n6. Mineral water\n7. Private car 10 hours','1. Breakfast\n2. Personal expenses at hot spring (extra drinks/snacks/spa)\n3. Gratuities\n3. Over time \n\n',NULL,'Minimum 2 participants required per booking\nJeep ride is not recommended for pregnant women or guests with severe back problems\nWarm jacket and closed shoes are highly recommended for sunrise hour\nCancellation policy applies','tour-packages/01KP1AABK406RW25GVM8M3J1X6.png',NULL,1350000.00,1050000.00,950000.00,NULL,'1 Day','Kintamani, Bali','Kintamani Tour',4.9,'fa-camera','Photography',1,1,2,'2026-03-31 07:50:02','2026-04-12 17:02:36'),(29,1,1,'Kintamani Heritage Village & Sacred Temple Journey','A journey through Bali’s highland heritage — where ancient traditions meet breathtaking landscapes.','kintamani-heritage-village-sacred-temple-journey','Escape into Bali’s serene highlands on a cultural journey rich in heritage, spirituality, and stunning scenery.\nAdmire panoramic Mount Batur views, explore the timeless beauty of Penglipuran Traditional Village, and visit the sacred Tirta Empul Temple in Tampak Siring.\nComplete your experience with a delicious lunch overlooking Kintamani’s volcanic landscape.\nA perfect day trip for culture lovers, families, and first-time Bali visitors.','1. Visit one of the most culturally preserved villages in Bali\n2. Witness traditional Balinese architecture, lifestyle, and hospitality\n3. Scenic highland journey with a mix of nature and heritage\n4. Visit a sacred water temple with optional purification ritual\n5. Perfect for culture enthusiasts, families, and first-time visitors','1. Kintamani Viewpoint – Take in panoramic views of Mount Batur and its shimmering crater lake.\n2. Penglipuran Traditional Village – Step back in time as you walk through bamboo forests and well-preserved Balinese homes with deep-rooted customs.\n3.Tirta Empul Temple (Tampak Siring) – Visit this holy temple complex known for its sacred water purification rituals.\n4. Lunch with a view - Enjoy a hearty lunch overlooking the beautiful highland terrain of Kintamani.\n\n','1. Private air-conditioned vehicle with English-speaking driver\n2. Entrance tickets to Kintamani, Penglipuran Village, and Tirta Empul Temple\n3. Lunch at a local restaurant with volcano view\n4. Mineral water\n5. Private car 10 hours','1. Personal expenses\n2. Local guide inside the temple or village\n3. Participation in melukat purification ritual (optional)\n4. Gratuities\n5. Overtime ',NULL,'Minimum 2 participants per booking\nModest attire is required for temple visit\nRespect local customs in traditional village\nCancellation policy applies\n\n','tour-packages/01KNBYHY1WW9DF09S1X73SGASG.png',NULL,975000.00,750000.00,650000.00,NULL,'1 Day','Kintamani, Bali','Kintamani Tour',4.9,'fa-camera','Photography',1,0,5,'2026-03-31 08:00:49','2026-08-04 08:43:44'),(30,1,1,'Uluwatu Sunset Romance Escape – Beaches, Clifftop Temple & Jimbaran ','A dreamy coastal escape through Bali’s most romantic and iconic southern spots.','uluwatu-sunset-romance-escape-beaches-clifftop-temple-jimbaran','Fall in love with Bali’s breathtaking southern coastline on this elegant sunset journey designed for couples. From the serene shores of Pandawa and the hidden beauty of Tanah Barak to the iconic cliffs of Uluwatu Temple, every stop is crafted for unforgettable moments. End the day with a dreamy beachfront seafood dinner at Jimbaran Bay as the sun melts into the ocean. Perfect for honeymooners, anniversaries, or a romantic Bali escape.','1. A scenic beach-hopping experience through Bali’s southern gems\n2. Romantic atmosphere throughout the tour\n3. Visit one of Bali’s most iconic temples\n4. Ideal for couples, honeymooners, or anniversary celebrations','1. Pandawa Beach – A tranquil white-sand beach known for its dramatic cliffs and clear waters — ideal for a relaxing stroll.\n2. Tanah Barak Beach – A hidden gem with picturesque limestone formations perfect for scenic photography.\n3. Padang-Padang Beach - A surfer’s paradise with a bohemian vibe and a great place for casual exploration or sunbathing.\n4. Uluwatu Temple – Perched atop a cliff, this sacred sea temple offers breathtaking views and a peaceful ambiance.\n5. Jimbaran Bay Sunset – End the day with a romantic seafood dinner on the beach, toes in the sand, watching the sun dip below the horizon.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. Entrance tickets to Pandawa Beach, Tanah Barak, Padang-Padang, Uluwatu Temple and Jimbaran\n3. Mineral water\n4. Private car 10 hours','1. Sunset seafood dinner at Jimbaran\n2. Kecak Dance ticket (optional, can be added upon request)\n3. Lunch or additional snacks during the tour\n4. Personal expenses (souvenirs, extra beverages, etc.)\n5. Sarong rental at the temple (available on-site)\n6. Gratuities\n7. Overtime',NULL,'Minimum 2 participants required per booking\nCasual beach attire recommended (plus modest clothing for temple visit)\nSunset visibility is weather-dependent\nCancellation policy applies','tour-packages/01KNFAN6MW5KT461GX6GQBX9PA.png',NULL,630000.00,511000.00,368000.00,NULL,'1 Day','South Bali','South Bali',5.0,'fa-camera','Photography',1,0,6,'2026-03-31 08:06:04','2026-04-05 17:22:12'),(31,1,1,'Bali Surf, Temple Sunset & Beach Club Luxe Escape','Ride the waves, chase sunsets, and vibe with Bali’s beach club scene.','bali-surf-temple-sunset-beach-club-luxe-escape','Catch the essence of Bali in one stylish day of surf, culture, and sunset indulgence.\nStart with an exciting beginner surf lesson at Kuta Beach, continue to the legendary Tanah Lot sea temple, and end with golden-hour cocktails at Potato Head Beach Club.\nDesigned for trend-conscious travelers, couples, and groups, this experience blends active fun with iconic island scenery.\nA perfect premium Bali day out from wave riding to beachfront sunset vibes.','1. Surf Bali’s most famous beach with expert guidance\n2. Cultural stop at one of Bali’s most picturesque temples\n3. VIP beach club experience in stylish Seminyak\n4. Perfect mix of activity, culture, and relaxation\n5. Great for young travelers, digital nomads, and lifestyle seekers','1. Kuta Beach + Surfing - Enjoy a beginner-friendly surfing session with professional instructors at Bali’s most iconic surfing beach.\n2. Tanah Lot Temple – Visit this dramatic seaside temple, perched on a rock in the ocean and beloved for its epic sunset views.\n3. Potato Head Beach Club – Lounge at Bali’s trendiest beach club with oceanfront pools, creative cocktails, and cool music.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. 1-hour beginner surf lesson (board & rash guard included)\n3. Entrance ticket to Tanah Lot Temple\n4. Mineral water','1. Beach club entry fee\n2. Meals and drinks beyond included credit at Potato Head\n3. Locker/towel rental at beach or surf school\n4. Personal expenses (extra drinks, souvenirs, etc.)\n5. Gratuities',NULL,'Minimum 2 participants required\nSurfing activity subject to sea conditions and tide schedules\nAdvance reservation required for surf lesson and beach club entry\nCancellation policy applies','tour-packages/01KP3PMRMRFGT4P6S3632WSS4Q.png',NULL,900000.00,795000.00,695000.00,NULL,'1 Day','South Bali','South Bali',5.0,'fa-camera','Photography',1,0,7,'2026-03-31 09:05:13','2026-04-13 15:16:29'),(32,1,1,'Bali Paragliding, Uluwatu Temple & Jimbaran Sunset Dinner Tour','Fly above Bali’s cliffs, visit iconic temples, and dine by the ocean.','bali-paragliding-uluwatu-temple-jimbaran-sunset-dinner-tour','Experience one of the best Bali adventure tours with an exciting paragliding flight over Melasti Beach’s dramatic cliffs and turquoise ocean.\nContinue your journey with free time at Melasti Beach, a visit to the iconic Uluwatu Temple, and a beautiful Jimbaran sunset seafood dinner by the sea.\nThis Bali day tour is perfect for couples, honeymooners, families, and adventure lovers seeking scenic views and unforgettable sunset moments.\nA complete South Bali experience combining thrill, culture, beach relaxation, and romantic dining.','1. Experience the thrill of paragliding over Bali’s dramatic cliffs.\n2. Relax and enjoy the pristine beauty of Melasti Beach.\n3. Explore one of Bali’s most iconic sea temples.\n4. Romantic seafood dinner on Jimbaran Beach.\n5. Perfect balance of adventure, culture, and leisure.','1. Paragliding at Melasti Beach – Fly over Bali’s cliffs and coastline with certified paragliding instructors.\n2. Melasti Beach – Relax and take stunning photos at one of Bali’s most beautiful white sand beaches.\n3. Uluwatu Temple – Visit Bali’s cliffside temple with panoramic ocean views.\n4. Jimbaran Bay Sunset – End the day with a romantic seafood dinner on the beach, toes in the sand, watching the sun dip below the horizon.','1. Private hotel transfers (AC vehicle with English-speaking driver)\n2. Paragliding session with professional instructor (all equipment included)\n3. Entrance tickets to Melasti Beach & Uluwatu Temple\n4. Mineral water','1. Personal expenses (extra drinks, souvenirs, etc.)\n2. Locker/towel rental at beach\n3. Jimbaran seafood dinner\n4. Optional kecak fire dance ticket at Uluwatu (if requested)\n5. Gratuities',NULL,'Minimum 2 participants required\nParagliding activity subject to weather and wind conditions\nAdvance booking required for paragliding\nCancellation policy applies','tour-packages/01KP3Q0EHDX395HEA3F0WTB9FE.png',NULL,1750000.00,1450000.00,1350000.00,NULL,'1 Day','South Bali','South Bali',5.0,'fa-camera','Photography',1,0,8,'2026-03-31 09:07:32','2026-04-13 15:22:52'),(33,1,1,'Bali Jetski, Suluban Beach & Uluwatu Sunset Cliff Tour','A perfect blend of ocean thrills and stunning cliffside views in South Bali.','bali-jetski-suluban-beach-uluwatu-sunset-cliff-tour','Discover one of the best South Bali adventure tours with an exciting solo jetski ride, hidden beach exploration, and iconic sunset temple views.\nFeel the thrill of riding freely across the ocean, continue to the dramatic Suluban Beach cave, then end your day at the legendary Uluwatu Temple overlooking the Indian Ocean.\nPerfect for couples, friends, and adventure lovers looking for Bali water sports, scenic cliffs, and unforgettable sunset moments.\nA complete South Coast Bali tour combining adrenaline, beach beauty, and culture.','1. Solo Jetski ride without instructor\n2. Explore Suluban Beach — one of Bali’s most unique cave beaches\n3. Visit Uluwatu Temple with panoramic cliff views\n4. Comfortable private car with English-speaking driver\n5. Perfect for couples, friends, and small groups','1. Jetski (Without Instructor)\nEnjoy a thrilling solo ride across the open ocean — no instructor on the back. Pure freedom and full-speed fun on the water.\n2. Suluban Beach\nA dramatic cave-access beach with turquoise waters and towering cliffs. Perfect for photos, relaxing, or exploring the hidden corners of Uluwatu.\n3. Uluwatu Temple\nOne of Bali’s most iconic cliff temples, offering breathtaking ocean views. Optional add-on: Kecak Fire Dance at sunset.','1. Jetski (without instructor)\n2. All entrance fees\n3. Private air-conditioned vehicle\n4. Hotel transfers\n5. English-speaking driver','1. Personal expenses\n2. Kecak Fire Dance ticket (optional)\n3. Meals\n4. Photo/video services',NULL,'Please confirm your booking in advance\nBring sunscreen and beachwear\nNot wheelchair accessible\nWaves at Suluban may vary depending on tide\nOptional dinner in Jimbaran available on request','tour-packages/01KP60EK2XAHDXBR51MHRTF6A1.png',NULL,1070000.00,820000.00,730000.00,NULL,'1 Day','South Bali','South Bali',5.0,'fa-camera','Photography',1,0,9,'2026-03-31 09:12:24','2026-04-14 12:46:21'),(34,1,1,'Bali Watersport Package: Jetski, Parasailing & Banana Boat Adventure','Experience the ultimate ocean adventure in South Bali!','bali-watersport-package-jetski-parasailing-banana-boat-adventure','Enjoy one of the best Bali watersport packages at Tanjung Benoa with three exciting activities in one trip.\nFeel the speed of a solo jetski ride, soar above the ocean with parasailing, and share laughs on a thrilling banana boat ride.\nPerfect for couples, friends, and families looking for Bali water sports, beach fun, and adrenaline-packed experiences in South Bali.\nA complete watersport adventure tour with private transfer and professional safety support.','1. Solo Jetski ride without instructor\n2. Parasailing adventure with stunning ocean views\n3. Fun Banana Boat ride with your group\n4. Safe and professional watersport operator\n5. Private car with English-speaking driver','1. Jetski (Without Instructor)\nEnjoy a thrilling solo ride across the open ocean — no instructor on the back. Pure adrenaline and full-speed fun.\n2. Parasailing\nFly high above the sea and enjoy breathtaking views of Bali’s coastline from the sky.\n3. Banana Boat\nRide together on an inflatable banana boat pulled by a speedboat — fun, splashes, and lots of laughter guaranteed!','1. Jetski (without instructor)\n2. Parasailing\n3. Banana Boat\n4. Safety equipment & insurance\n5. Private air-conditioned vehicle\n6. Hotel transfers\n7. English-speaking driver','1. Personal expenses\n2. Photo/video documentation\n3. Meals',NULL,'1. Advance booking required\n2. Bring sunscreen and extra clothes\n3. Minimum age & weather conditions apply\n4. Activities depend on sea conditions','tour-packages/01KP60M6MM6RPM05PESXQV6NAB.png',NULL,1300000.00,1050000.00,930000.00,NULL,'1 Day','South Bali','South Bali',5.0,'fa-camera','Photography',1,0,10,'2026-03-31 09:15:36','2026-04-14 12:49:25'),(35,1,1,'Tulamben Diving Tour: USS Liberty Shipwreck & Coral Garden Experience','Explore Bali’s underwater treasures — dive into history and marine beauty.','tulamben-diving-tour-uss-liberty-shipwreck-coral-garden-experience','Discover one of the best Bali diving experiences at Tulamben, home to the world-famous USS Liberty Shipwreck and vibrant Coral Garden reef.\nThis Bali dive tour includes 2 guided dives in calm, crystal-clear waters, perfect for beginners and certified divers alike.\nExplore colorful coral reefs, tropical fish, sea turtles, and one of Bali’s most iconic underwater historical sites.\nA must-do East Bali adventure for ocean lovers, first-time divers, and underwater photography enthusiasts.','1. Dive Bali’s most famous wreck site with expert guidance\n2. Explore vibrant marine life and healthy coral reefs\n3. Ideal for first-time and certified divers\n4. All gear and safety equipment included\n5. Small-group dive experience in crystal-clear waters','1. USS Liberty Shipwreck – Dive into history and marine biodiversity at this iconic 120-meter sunken warship, now a thriving underwater reef.\n2. Coral Garden – A colorful, shallow dive site with gentle currents, perfect for spotting macro life and taking amazing underwater photos.','1. Return hotel transfers (AC vehicle with English-speaking driver)\n2. 2 dives at Tulamben (USS Liberty & Coral Garden)\n3. Dive guide/instructor (PADI-certified)\n4. Full diving equipment rental\n5. Local entrance fees and marine contributions','1. Underwater photography or video\n2. Personal expenses (snacks, souvenirs)\n3. Optional tip for dive guide/crew\n4. Additional dive or fun dive extension',NULL,'Minimum 2 participants required\nSuitable for ages 12+\nDivers must be in good health; a medical questionnaire will be provided\nTour is weather-dependent; may be rescheduled if sea conditions are unsafe\nCancellation policy applies\n\n','tour-packages/01KP60S7BWFJXBGR60EYY38KSK.png',NULL,2052000.00,1712000.00,1453000.00,NULL,'1 Day','East Bali','East Bali',5.0,'fa-camera','Photography',1,0,11,'2026-03-31 09:19:25','2026-04-14 12:52:10'),(36,1,5,'SUNRISE HORSE RIDING – BEACH EXPERIENCE','Best Bali Sunrise Horse Riding – Black Sand Beach & Ocean View','sunrise-horse-riding-beach-experience','Experience the beauty of Bali with Saba Sunrise Horse Riding, a peaceful and unforgettable ride along the black sand beach of Saba. Start your morning with a stunning sunrise view while riding a well-trained horse guided by professional handlers. This activity offers a perfect combination of relaxation, nature, and unique Bali experience—ideal for couples, families, and beginners.','1. Sunrise horse riding at Saba Beach\n2. Ride along black sand beach with ocean view\n3. Calm and relaxing morning experience\n4. Well-trained horses and professional guides\n5. Suitable for beginners and all levels\n6. Perfect for couples and families\n7. Hotel pick-up and drop-off included','1. Early morning hotel pick-up\n2. Arrival at Saba Beach\n3. Sunrise horse riding experience (approx. 1 hour)\n6. Return transfer to hotel','1. Horse riding experience (approx. 1 hour)\n2. Professional guide/handler\n3. Safety equipment (helmet)\n4. Insurance coverage\n5. Private hotel transfer (pick-up and drop-off)\n6. Drinking water','1. Personal expenses\n2. Photo and video documentation\n3. Tips / gratuities',NULL,'1. Minimum age: 7 years old\n2. Maximum weight: 80 kg \n3. Not recommended for pregnant women\n4. Not suitable for participants with serious medical conditions\n5. Sunrise experience depends on weather conditions\n6. Participants must follow all safety instructions\n7. Activity operates in all weather conditions\n8. Advance booking is required\n9. Hotel transfer is included for Central Bali areas. Additional charge applies for pick-up and drop-off outside Central Bali','tour-packages/01KQ7G04TP2YBM3B9GEGWE6F3D.png',NULL,1400000.00,1270000.00,1150000.00,NULL,'Half Day','Bali','East Bali',5.0,'fa-camera','Photography',1,0,0,'2026-03-31 09:21:41','2026-05-17 09:37:49'),(37,1,1,'East Bali Royal Water Palace & Virgin Beach Tour','Discover the charm of Bali’s eastern coast through royal water palaces and a hidden white-sand beach.','east-bali-royal-water-palace-virgin-beach-tour','This tour blends history, architecture, mountain views, and relaxing beach time — perfect for travelers who want scenic beauty with a peaceful vibe.','1. Visit the majestic Taman Ujung Water Palace\n2. Explore the iconic Tirta Gangga\n3. Relax at the beautiful Virgin Beach (White Sand Beach)\n4. Mountain, ocean, and garden scenery in one day\n5. Perfect mix of culture, nature, and beach time\n6. Private, comfortable air-conditioned vehicle','1. Taman Ujung Water Palace\nA former royal palace featuring large pools, bridges, and elegant Balinese-European architecture with scenic views toward the sea and mountains.\n2. Tirta Gangga\nA famous water garden with fountains, koi ponds, and stepping stones where visitors can walk across the water for unique photos.\n3. Virgin Beach (White Sand Beach)\nA hidden beach in East Bali with soft sand, clear water, and a relaxing atmosphere. Ideal for swimming, sunbathing, or enjoying fresh seafood at local beach cafes.','1. All entrance fees (Taman Ujung & Tirta Gangga)\n2. Virgin Beach entrance\n3. Private air-conditioned vehicle\n4. Hotel pickup & drop-off\n5. English-speaking driver\n6. Parking & fuel','1. Lunch / food & drinks\n2. Sunbed rental at the beach (optional)\n3. Personal expenses\n4. Optional photo/video services\n5. Tips & gratuities',NULL,'1. Advance booking required\n2. Bring swimwear, towel, and sunscreen\n3. Comfortable walking shoes recommended\n4. Not wheelchair accessible\n5. Weather and sea conditions may affect beach activities','tour-packages/01KRNF5BCACMF4SWVBNS9JQ2RF.png',NULL,900000.00,600000.00,480000.00,NULL,'1 Day','East Bali','East Bali',5.0,'fa-camera','Photography',1,0,13,'2026-03-31 09:28:05','2026-05-15 09:23:27'),(38,1,1,'Lovina Sunrise Dolphin Experience','A magical sunrise boat journey with wild dolphins in North Bali’s calm ocean','lovina-sunrise-dolphin-experience','Start your Bali morning with a magical sunrise boat trip at Lovina Beach, where playful wild dolphins swim freely in their natural habitat.\nThis peaceful North Bali experience is perfect for early risers, couples, families, and photographers seeking unforgettable sunrise moments on the ocean.','1. Watch wild dolphins in their natural habitat at sunrise\n2. Private traditional boat experience at Lovina\n3. Peaceful North Bali ocean scenery\n4. Perfect for couples, families, and photographers\n5. Magical sunrise moments on calm waters','1. Lovina Dolphin Tour – A sunrise boat ride to witness dolphins swimming freely in their natural habitat.\n','1. Round-trip hotel transfer\n2. Private air-conditioned vehicle\n3. English-speaking driver\n4. Private Lovina dolphin boat\n5. Swimming with Dolphin \n5. Mineral water\n6. Private car 10 hours','1. Breakfast / meals\n2. Personal expenses\n3. Photo / drone services\n4. Tips for boat captain\n5. Overtime charge',NULL,'Minimum 2 participants\nPick-up time: 03:00–03:30 AM (depending on hotel location)\nDolphin sightings are natural and not guaranteed, but highly likely\nLife jackets available upon request for the boat ride\nCancellation policy applies','tour-packages/01KP16X3AF09PF738A8H6T9HHF.png',NULL,1100000.00,850000.00,690000.00,NULL,'1 Day','North Bali','North Bali',5.0,'fa-camera','Photography',1,1,1,'2026-03-31 09:30:45','2026-06-06 02:50:24'),(39,1,1,'North Bali Mystical Escape: Handara Gate, Ulun Danu & Banyumala Waterfall','A mystical journey through temples, waterfalls, and highland serenity.','north-bali-mystical-escape-handara-gate-ulun-danu-banyumala-waterfall','Escape to the cool highlands of North Bali on a scenic journey filled with iconic landmarks, sacred temples, and hidden waterfalls. Capture stunning photos at the famous Handara Gate, admire the floating beauty of Ulun Danu Beratan Temple, and refresh yourself at the magical Banyumala Twin Waterfalls. Perfect for couples, nature lovers, and travelers seeking Bali’s peaceful mountain charm.','📸 Iconic Handara Gate photo stop\n🛕 Visit Ulun Danu Beratan Temple by the lake\n🌿 Explore Banyumala Twin Waterfalls\n🌲 Scenic Bedugul forest drive\n💑 Perfect for nature lovers & couples','1. Handara Gate – Take Instagram-worthy shots at one of Bali’s most iconic photo locations\n2. Beratan Lake & Ulun Danu Temple – Explore the peaceful floating temple in the heart of the highlands\n3. Banyumala Twin Waterfall – Trek through lush jungle trails to discover a hidden twin cascade\n4. Bedugul Forest Drive – Enjoy a cool and calming journey through the mountain jungle','1. Private AC vehicle with English-speaking driver\n2. Entrance tickets to all attractions\n3. Mineral water\n4. Private car 10 hours','1. Lunch\n2. Personal Expenses\n3. Gratuities\n4. Overtime',NULL,'Minimum 2 participants\nModerate fitness required for waterfall trek (approx. 15–20 minutes walking down and up)\nBring swimwear, change of clothes, and waterproof footwear\nWeather in Bedugul is cooler — light jacket recommended\nCancellation policy applies','tour-packages/01KNF9DAW5JJSDCY75HCMT10YH.png',NULL,907500.00,644000.00,462000.00,NULL,'1 Day','North Bali','North Bali',4.9,'fa-camera','Photography',1,0,15,'2026-03-31 09:33:34','2026-04-05 17:00:25'),(40,1,1,'Jatiluwih UNESCO Highlands Tour – North Bali Scenic Escape','Experience Bali’s breathtaking highlands, sacred temples, and world-famous rice terraces in one beautiful full-day journey.','jatiluwih-unesco-highlands-tour-north-bali-scenic-escape','Discover Bali’s most beautiful highland landscapes in one relaxing full-day trip. Visit the iconic Handara Gate, the floating Ulun Danu Beratan Temple, and the breathtaking Jatiluwih Rice Terraces, a UNESCO World Heritage Site. Perfect for couples, families, and nature lovers seeking Bali’s cool mountain charm.','1. Visit the iconic Handara Gate – a must-have Instagram photo spot\n2. Explore Ulun Danu Beratan Temple floating on the lake\n3. Walk through the vast UNESCO-listed Jatiluwih Rice Terraces\n4. Enjoy Bali’s cool highland climate and scenic mountain views\n5. Private car & driver for a comfortable, relaxed experience\n6. Great for couples, families, and big groups','1. Handara Gate\nA famous giant Balinese gate surrounded by lush mountains — perfect for beautiful photos.\n2. Ulun Danu Beratan Temple\nA serene temple floating on Lake Beratan, known for its fresh air and stunning scenery.\n3. Jatiluwih Rice Terrace (UNESCO)\nBali’s largest rice terrace and a UNESCO World Heritage Site, showcasing traditional Subak irrigation and breathtaking valley views.','1. Private air-conditioned vehicle\n2. Hotel transfers\n3. English-speaking driver\n4. All Entrance Tickets\n5. Parking fees & petrol\n6. Private car 10 hours','1. Personal expenses\n2. Meals\n3. Overtime',NULL,'Please contact us prior to booking for smooth arrangements\nBring sunscreen, comfortable shoes, and some cash\nNot wheelchair accessible\nWeather conditions may affect visibility in the highlands\nContact us for pickup outside designated areas','tour-packages/01KNF9ZH72KP1DQVPSS8KV1V08.jpg',NULL,925000.00,600000.00,500000.00,NULL,'1 Day','North Bali','North Bali',5.0,'fa-camera','Photography',1,0,16,'2026-03-31 09:37:25','2026-04-05 17:10:22'),(41,1,1,'Sekumpul Waterfall & North Bali Scenic Tour','An unforgettable journey to the most breathtaking natural and cultural highlights of North Bali.','sekumpul-waterfall-north-bali-scenic-tour','This tour combines Bali’s most spectacular waterfalls with iconic landmarks and cool mountain scenery — perfect for nature lovers and photography seekers.','1. Explore the majestic Sekumpul Waterfall\n2. Visit the scenic Hidden Waterfall\n3. Discover the dramatic Fiji Waterfall\n4. Photo stop at the iconic Handara Gate\n5. Visit the famous Ulun Danu Beratan Temple\n6. Stunning mountain, jungle, and lake views throughout the day\n7. Private, comfortable air-conditioned vehicle','1. Sekumpul Waterfall\nOften called Bali’s most beautiful waterfall, surrounded by lush jungle and towering cliffs. A scenic trek leads you to this powerful and photogenic natural wonder.\n2. Hidden Waterfall\nA peaceful and lesser-known waterfall near Sekumpul, offering a quieter atmosphere and beautiful natural surroundings.\n3. Fiji Waterfall\nA dramatic twin waterfall with wide cascading flows, located in the same area and perfect for nature photography.\n4. Handara Gate\nOne of Bali’s most famous photo spots, featuring a traditional Balinese gate set against a mountain backdrop.\n5. Ulun Danu Beratan Temple\nA stunning water temple located on Lake Beratan, one of Bali’s most iconic landmarks surrounded by cool mountain air.','1. All entrance fees\n2. Local trekking guide (Sekumpul waterfall area)\n3. Private air-conditioned vehicle\n4. Hotel pickup & drop-off\n5. English-speaking driver\n6. Parking & fuel\n\n','1. Lunch\n2. Personal expenses\n3. Optional photo/video services\n4. Tips & gratuities\n\n',NULL,'1. Advance booking is required\n2. Moderate trekking required — wear comfortable walking shoes\n3. Not recommended for guests with mobility issues\n4. Bring sunscreen and change of clothes\n5. Weather and road conditions may affect timing\n6. Guests must follow local guide instructions during trekking\n\n','tour-packages/01KN1M7HFZAYYK1FCDBWA5BFDT.jpg',NULL,1200000.00,850000.00,745000.00,NULL,'1 Day','North Bali','North Bali',5.0,'fa-camera','Photography',1,0,17,'2026-03-31 09:40:08','2026-04-02 13:44:35'),(42,1,1,'Lake Beratan Boat Ride & Jatiluwih Highlands Tour','Experience Bali’s cool mountain region with a relaxing boat ride on Lake Beratan, iconic temple views, and breathtaking UNESCO rice terraces.','lake-beratan-boat-ride-jatiluwih-highlands-tour','This tour is perfect for travelers who love scenic landscapes, fresh air, and peaceful highland vibes.\n\n','1. Enjoy a boat ride on Lake Beratan with mountain views\n2. Visit the iconic Ulun Danu Beratan Temple\n3. Stop at a local Strawberry Farm in Bedugul\n4. Explore the UNESCO-listed Jatiluwih Rice Terraces\n5. Beautiful highland scenery all day\n6. Private, comfortable air-conditioned vehicle','1. Lake Beratan Boat Ride\nEnjoy a peaceful ride across Lake Beratan, surrounded by cool mountain air and scenic views. A unique way to experience Bali’s highland landscape.\n2. Ulun Danu Beratan Temple\nOne of Bali’s most famous landmarks, this beautiful water temple appears to float on the lake and is set against a backdrop of mountains and misty air.\n3. Strawberry Farm (Bedugul Area)\nVisit a local strawberry farm where you can walk around, take photos, and try fresh strawberries or strawberry-based snacks (seasonal).\n4. Jatiluwih Rice Terraces\nA UNESCO World Heritage site featuring vast, stunning rice terraces with fresh mountain scenery — perfect for short walks and panoramic photos.','2. Boat ride at Lake Beratan\n3. Private air-conditioned vehicle\n4. Hotel pickup & drop-off\n5. English-speaking driver\n6. Parking & fuel','1. Lunch\n2. Personal expenses\n3. Optional snacks or strawberry purchases\n4. Optional photo/video services',NULL,'1. Advance booking required\n2. Bring a light jacket (cool weather in highlands)\n3. Weather and lake conditions may affect boat operations\n4. Comfortable walking shoes recommended\n5. Not wheelchair accessible','tour-packages/01KN1MD2KSY1KD4GS7W4D2WGA7.jpg',NULL,1150000.00,770000.00,670000.00,NULL,'1 Day','North Bali','North Bali',4.9,'fa-camera','Photography',1,0,18,'2026-03-31 09:43:09','2026-04-02 13:44:35'),(43,1,3,'Honeymoon Package 5D4N','Celebrate Love in Bali – Romance, Culture & Blissful Escapes','honeymoon-package-5d4n','Step into your new chapter of life with a romantic 5-day journey across Bali’s most scenic and soulful destinations.\nThe Honeymoon Package 5D4N. is thoughtfully crafted to combine luxury, adventure, and intimate experiences in paradise — perfect for newlyweds or couples seeking a memorable getaway.','1. Romantic dinner on your first night in Bali\n2. Beach club vibes, jungle swing & ATV adventure\n3. Cultural touchpoints: temples, traditional village, and sacred springs\n4. Bali’s most iconic natural and spiritual attractions\n5. Ideal balance of relaxation, love, and light adventure\n\n','Day 1 – Arrival & Romantic Welcome\n∙ Pick-up at Ngurah Rai International Airport\n∙ Hotel check-in at a romantic honeymoon suite or villa\n∙ Evening romantic candlelight dinner by the beach at Jimbaran\n\nDay 2 – Sun, Sea & Chic Beach Club\n∙ Morning visit to the stunning Melasti Beach\n∙ Explore cliffside temple Uluwatu with panoramic ocean views\n∙ Sunset vibes at Finns Beach Club with cocktails and ocean breeze\n\nDay 3 – Cultural Highlands Exploration\n∙ Visit sacred Tirta Empul Temple (Tampak Siring) for a blessing ritual\n∙ Stroll through the traditional Penglipuran Village\n∙ Lunch with a view at Kintamani, overlooking Mount Batur\n\nDay 4 – Nature, Thrill & Sunset Icon\n∙ Discover Tanah Lot Temple, Bali’s iconic sea temple\n∙ Swing and sip at Alas Harum, an Ubud jungle gem\n∙ Exciting ATV ride through rice fields and countryside\n\nDay 5 – Farewell & Airport Drop-off\n∙ Breakfast and leisure time\n∙ Hotel check-out\n∙ Private transfer to the airport','Dinner at Jimbaran on Day 1\nPrivate transportation with English-speaking driver\nEntrance fees for all destinations\nATV ride + safety gear\nBottled water during the tour\nAirport transfers (pick-up & drop-off)','4 nights stay in romantic villa/hotel\nDaily breakfast\nLunch and dinner\nAlcoholic drinks at beach clubs/restaurants\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)',NULL,'Minimum 2 adults (honeymooners or couples)\nActivities are weather dependent and may be adjusted for safety\n50% deposit required upon booking, full payment before arrival\nFree cancellation up to 7 days prior to arrival\nHoneymoon decoration or flower bath upon request (based on hotel policy)\n\n','tour-packages/01KN1MN01CZXS6R7EZT28WQQDX.jpg',NULL,4000000.00,NULL,NULL,NULL,'5 Day 4 Night','Bali',NULL,5.0,'fa-heart','Romantic',1,0,19,'2026-03-31 09:47:29','2026-07-29 02:38:20'),(44,1,3,'Honeymoon Package 6D5N','The Ultimate Romantic Escape Across Bali’s Most Breathtaking Corners','honeymoon-package-6d5n','Experience love in full bloom with this 6-day honeymoon journey designed to blend romantic luxury, spiritual serenity, and awe-inspiring nature.\nFrom candlelit dinners and beach sunsets to sacred temples, mountain springs, and even a dolphin sunrise, this itinerary is the perfect blend of intimacy and adventure.\nWhether you\'re newlyweds or celebrating love, this package offers the ideal setting to create unforgettable memories with your partner — from Bali’s southern shores to its northern treasures and Nusa Penida’s dramatic cliffs.','1. Romantic dinner on your first night in Bali\n2. Sunset moments at Uluwatu & beach club relaxation\n3. Sacred temple blessings & rejuvenating hot springs\n4. Dolphin sunrise cruise at Lovina\n5. Day trip to Nusa Penida\'s most iconic cliffs & beaches\n6. Carefully curated for romance, relaxation, and exploration','Day 1 – Romantic Arrival\n∙ Pick-up at Ngurah Rai Airport\n∙ Check-in at romantic villa/hotel\n∙ Evening romantic candlelight dinner at Jimbaran Beach\n\nDay 2 – Ocean Serenity & Sunset Glamour\n∙ Morning visit to the picturesque Melasti Beach\n∙ Explore majestic Uluwatu Temple\n∙ Sunset & cocktails at Finns Beach Club\n\nDay 3 – Highland Bliss & Hot Springs\n∙ Scenic drive to Kintamani, with stunning views of Mt. Batur\n∙ Visit Tirta Empul Temple (Tampak Siring)\n∙ Relaxation at Kintamani Hot Spring\n\nDay 4 – Sacred North & Sunrise with Dolphins\n∙ Early departure to Lovina Beach for a Dolphin Tour\n∙ Visit the serene Ulun Danu Beratan Temple on Lake Beratan\n\nDay 5 – Nusa Penida Wonders\n∙ Boat trip to Nusa Penida\n∙ Explore Kelingking Beach, Broken Beach, Angel’s Billabong, and Crystal Bay\n\nDay 6 – Farewell & Departure\n∙ Breakfast and leisure time\n∙ Hotel check-out\n∙ Airport transfer\n\n','Dinner at Jimbaran on Day 1\nPrivate A/C transportation with English-speaking driver\nReturn fast boat to Nusa Penida\nEntrance & activity fees at all listed destinations\nDolphin tour & boat\nBottled mineral water during the tour\nAirport pick-up & drop-off\n','Daily breakfast\nLunch and dinner\nAlcoholic drinks at beach clubs/restaurants\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)',NULL,'Package valid for minimum 2 adults (honeymooners or couples)\n50% deposit is required to confirm booking\nFull payment must be completed before arrival\nFree cancellation up to 7 days before arrival\nTour schedules may adjust due to weather conditions or safety protocols\nDolphin sightings are natural and cannot be guaranteed, but highly likely\n\n','tour-packages/01KN1MTBSBEM14YQC3T0FHXZZ6.jpg',NULL,4700000.00,NULL,NULL,NULL,'6 Day 5 Night','Bali',NULL,5.0,'fa-heart','Romantic',1,0,20,'2026-03-31 09:50:25','2026-04-02 13:44:35'),(45,1,3,'Honeymoon Package 7D6N','Embark on a breathtaking 7-day romantic journey through Bali\'s most iconic, spiritual, and serene destinations.','honeymoon-package-7d6n','Designed for couples seeking a balance of adventure, intimacy, culture, and wellness, this honeymoon package combines Bali’s coastal beauty, majestic temples, exhilarating activities, and peaceful natural escapes — perfect for creating once-in-a-lifetime memories.\nWhether you\'re newlyweds or celebrating your anniversary, this itinerary lets your love blossom in paradise.','1. Romantic dinner on your first night in Bali\n2. Thrilling ATV and iconic Bali Swing photo experience\n3. Dolphin watching at sunrise in Lovina\n4. Sunset views from Uluwatu and beach club lounging\n5. Full-day island escape to Nusa Penida\n6. Visits to Bali’s most sacred temples and hidden natural treasures\n7. Seamless mix of adventure, romance, and serenity\n\n','Day 1 – Warm Welcome & Romantic Dinner\n∙ Airport pick-up\n∙ Check-in at romantic villa/hotel\n∙ Candlelight dinner on the sands of Jimbaran Bay\n\nDay 2 – Ubud Adventure & Romance\n∙ Morning ATV ride through the countryside\n∙ Photo moments at Bali Swing\n∙ Refreshing visit to Tegenungan Waterfall\n\nDay 3 – Sunset & Chill by the Sea\n∙ Morning at Melasti Beach\n∙ Explore Uluwatu Temple on the cliff\n∙ Sunset at Finns Beach Club\n\nDay 4 – Dolphin Sunrise & Sacred North\n∙ Early trip to Lovina Beach for Dolphin Watching\n∙ Visit to Ulun Danu Beratan Temple on the lake\n\nDay 5 – Island Paradise: Nusa Penida\n∙ Boat transfer to Nusa Penida\n∙ Explore Kelingking Beach, Broken Beach, Angel’s Billabong, and Crystal Bay\n\nDay 6 – The Eastern Sacred Trail\n∙ Sunrise visit to Pura Lempuyang (Heaven’s Gate)\n∙ Continue to Pura Besakih, the mother temple\n∙ Walk through royal gardens at Tirta Gangga\n\nDay 7 – Farewell & Departure\n∙ Breakfast and free time\n∙ Check-out and transfer to airport','Dinner at Jimbaran on Day 1\nPrivate air-conditioned transportation with English-speaking driver\nReturn fast boat to Nusa Penida\nATV ride and Bali Swing activity\nEntrance tickets to all mentioned attractions\nDolphin tour with traditional boat\nBottled mineral water during the tour\nAirport pick-up and drop-off\n\n','6 nights stay in romantic villa/hotel\nDaily breakfast\nLunch and dinner\nAlcoholic drinks at beach clubs/restaurants\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)\n\n',NULL,'Package valid for minimum 2 adults (honeymooners or couples)\n50% deposit is required to confirm booking\nFull payment must be completed before arrival\nFree cancellation up to 7 days before arrival\nTour schedules may adjust due to weather conditions or safety protocols\nDolphin sightings are natural and cannot be guaranteed, but highly likely\nEarly departure on certain days may be required (for sunrise or island tours)\n\n','tour-packages/01KN1MZF4TEDS8JMBA6WET8P6N.jpg',NULL,6570000.00,NULL,NULL,NULL,'7 Day 6 Night','Bali',NULL,5.0,'fa-heart','Romantic',1,0,21,'2026-03-31 09:53:12','2026-04-02 13:44:35'),(46,1,2,'Adventure Package 5D4N','A 5-Day Thrill-Filled Journey Across Bali’s Land, Sea, and Culture','adventure-package-5d4n','Experience Bali like never before with our 5D4N Adventure Package — a bold blend of sea adventures, jungle rides, iconic temples, and island escapades.\nPerfect for travelers who crave both adrenaline and authenticity, this itinerary takes you from white sand beaches and sacred cliffs to river rapids, quad bike tracks, and the breathtaking cliffs of Nusa Penida.\nLet us take care of every detail while you immerse yourself in Bali’s natural beauty, spiritual soul, and action-packed experiences.','1. Perfect balance of adventure, nature, and iconic destinations\n2. Action-packed days with ATV, rafting, and banana boat fun\n3. Discover the jaw-dropping cliffs of Kelingking Beach\n4. Witness Bali’s culture through temples, dances, and sacred landscapes\n5. Hassle-free journey with everything arranged for you','Day 1 – Arrival & Sunset Welcome\n∙ Pick-up at Ngurah Rai International Airport\n∙ Hotel check-in and refresh\n∙ Evening at Jimbaran Beach for a relaxed sunset or optional seafood dinner\n\nDay 2 – Watersports & Cultural Landmarks\n∙ Morning Banana Boat ride at Tanjung Benoa\n∙ Visit to stunning Melasti Beach\n∙ Cultural immersion at Garuda Wisnu Kencana (GWK) Park\n∙ Sunset at Uluwatu Temple + Kecak Fire Dance performance\n\nDay 3 – Jungle Rush & Ubud Beauty\n∙ Morning ATV ride through forests and rural tracks\n∙ White Water Rafting (2 hours) along the Ayung River\n∙ Soar on the Ubud Swing\n∙ Visit the stunning Tegalalang Rice Terrace\n\nDay 4 – Island Escape to Nusa Penida\n∙ Speedboat to Nusa Penida (West Side)\n∙ Explore Kelingking Beach, Broken Beach, Angel’s Billabong\n∙ Chill and swim at Crystal Bay\n∙ Return to Bali mainland\n\nDay 5 – Departure Day\n∙ Hotel checkout\n∙ Private transfer to the airport','Return fast boat to Nusa Penida + island transportation\nPrivate AC vehicle with English-speaking driver\nEntry fees and activity equipment (rafting, ATV, swing, watersport)\nBottled water during tours','4 nights hotel accommodation\nLunch and dinner\nPersonal expenses (souvenirs, extra drinks)\nTips for driver/guide (optional)\n\n',NULL,'Minimum 2 participants required\nActivities are weather dependent and may be adjusted for safety\n50% deposit required upon booking, full payment before arrival\nFree cancellation up to 7 days prior to arrival\n\n','tour-packages/01KN1NBNQ6Z5F0SE2SKH3H2CEY.jpg',NULL,4000000.00,3050000.00,2675000.00,NULL,'5 Day 4 Night','Bali',NULL,5.0,'fa-compass','Adventure',1,0,22,'2026-03-31 09:59:52','2026-04-02 13:44:35'),(47,1,4,'Family Package 4D3N','Spend quality time with your loved ones on a heartwarming 4-day Bali adventure designed for families.','family-package-4d3n','This carefully curated itinerary combines wildlife encounters, nature exploration, beachside relaxation, and cultural moments, ensuring a joyful experience for both children and adults.\nWith seamless logistics, family-friendly attractions, and engaging experiences, this trip offers the perfect balance of fun and comfort for unforgettable family memories in the Island of the Gods.\n\n','1. Family-friendly visit to Bali Safari & Marine Park\n2. Meet and feed animals at Exotic Marine Park\n3. Cultural immersion at Uluwatu and lush rice fields\n4. Interaction with monkeys in their natural habitat\n5. Leisure beach time with stunning ocean views\n6. Seamless private tour experience with child-friendly pacing\n\n','Day 1 – Arrival & Sunset Welcome\n∙ Airport pick-up\n∙ Hotel check-in\n∙ Leisure time followed by a scenic sunset at Jimbaran Beach\n\nDay 2 – Wildlife & Culture Adventure\n∙ Morning at Bali Safari & Marine Park: elephants, tigers, safari rides\n∙ Meet the cheeky residents of the Ubud Monkey Forest\n∙ Visit the iconic Tegalalang Rice Terrace\n\nDay 3 – Marine Fun & Coastal Beauty\n∙ Educational and entertaining visit to Bali Exotic Marine Park\n∙ Explore Uluwatu Temple on the cliffs\n∙ Beach play and relaxation at Melasti Beach\n\nDay 4 – Departure\n∙ Breakfast, leisure time\n∙ Hotel check-out and airport drop-off','Private air-conditioned vehicle with English-speaking driver\nAdult entrance tickets to Bali Safari & Marine Park and Bali Exotic Marine Park\nEntrance tickets to Jimbaran, Monkey Forest, Uluwatu Temple, and Melasti Beach\nAirport pick-up and drop-off','3 nights stay at family-friendly hotel or villa\nDaily breakfast\nLunch and dinner\nPersonal expenses (snacks, souvenirs, laundry, etc.)\nEntrance tickets for children:\n∙ Bali Safari child ticket : IDR 250,000\n∙ Bali Exotic Marine Park child ticket : IDR 350,000\nGratuities for driver/guide (optional)',NULL,'Minimum 2 participants required\nItinerary may be adjusted depending on weather or attraction availability\n50% deposit required to confirm booking\nFree cancellation up to 7 days prior to arrival\nNote: Prices are for adult tickets. Children require additional entrance fees.\nBali Safari child ticket: IDR 250,000\nBali Exotic Marine Park child ticket : IDR 350,000\nOther attractions may vary by age and height — please inquire upon booking.','tour-packages/01KN1NPB3819H8VTP8RJ1Q20RQ.jpg',NULL,4050000.00,3100000.00,2730000.00,NULL,'4 Day 3 Night','Bali',NULL,4.9,'fa-children','Family',1,0,23,'2026-03-31 10:05:41','2026-04-02 13:44:35'),(48,1,4,'Family Package 5D4N','Take your family on a magical 5-day journey through Bali that blends relaxation, adventure, and cultural immersion.','family-package-5d4n','From exciting wildlife encounters to serene sunsets and fun beach moments, this package is tailored for families seeking a balanced, joyful, and enriching holiday experience.\nWhether you’re marveling at dolphins at sunrise or laughing together at the monkey forest, each day is packed with memories your family will cherish forever.','1. Exciting dolphin tour at sunrise\n2. Up-close safari adventure at Bali Safari Park\n3. Cultural charm at Ulun Danu Beratan Temple\n4. Fun moments at Seminyak & Melasti beaches\n5. Cultural exploration in Ubud and cliffside Uluwatu\n6. Family-friendly pacing with private transport','Day 1 – Welcome to Bali\n∙ Airport pick-up\n∙ Hotel check-in\n∙ Leisure time followed by a scenic sunset at Jimbaran Beach\n\nDay 2 – Southern Bali Leisure\n∙ Visit Uluwatu Temple with ocean cliff views\n∙ Free time and play at Melasti Beach\n∙ Evening stroll and cafe time at Double Six Seminyak\n\nDay 3 – Wild Encounters & Nature\n∙ Explore Bali Safari & Marine Park\n∙ Meet the monkeys at Ubud Monkey Forest\n∙ Stop by the beautiful Tegalalang Rice Terrace\n\nDay 4 – Northern Wonder\n∙ Early trip to Lovina Beach for a dolphin-watching boat tour\n∙ Visit the stunning Pura Ulun Danu Beratan temple on the lake\n\nDay 5 – Departure\n∙ Breakfast and leisure\n∙ Hotel check-out and airport transfer\n','Private air-conditioned vehicle with English-speaking driver\nAdult entrance tickets to Bali Safari & Marine Park\nEntrance tickets to all mentioned destinations\nDolphin boat tour at Lovina\nBottled mineral water during tours\nAirport pick-up and drop-off\n','4 nights stay at family-friendly hotel or villa\nDaily breakfast\nLunch and dinner\nPersonal expenses (snacks, souvenirs, laundry, etc.)\nEntrance tickets for children:\n∙ Bali Safari child ticket : IDR 250,000\nGratuities for driver/guide (optional)',NULL,'Minimum 2 participants required\nItinerary may be adjusted depending on weather or attraction availability\n50% deposit required to confirm booking\nFree cancellation up to 7 days prior to arrival\nNote: Prices are for adult tickets. Children require additional entrance fees.\nBali Safari child ticket: IDR 250,000\nOther attractions may vary by age and height — please inquire upon booking.\n\n','tour-packages/01KQ7EQ4ZXHW5JNKTZV7J29JYY.png',NULL,3950000.00,2700000.00,2350000.00,NULL,'5 Day 4 Night','Bali',NULL,4.9,'fa-children','Family',1,0,24,'2026-03-31 10:10:51','2026-04-27 12:30:38'),(49,1,4,'Family Package 6D5N','Bring your whole family along for a perfectly curated 6-day, 5-night Bali escape that blends fun, culture, nature, and relaxation.','family-package-6d5n','This package is ideal for families wanting to experience the best of Bali in one complete journey, from dolphin watching to temple visits, beach fun to hot spring relaxation.\nLet us handle all the planning while you enjoy stress-free quality time with your loved ones.\n\n','1. Thrilling banana boat ride for all ages\n2. Wildlife safari adventure at Bali Safari Park\n3. Sunrise dolphin tour at Lovina\n4. Sacred temples and rice fields of Ubud and Kintamani\n5. Cultural show at Uluwatu cliff temple\n6. Relaxing hot spring experience in the highlands','Day 1 – Arrival & Sunset Welcome\n∙ Airport pick-up\n∙ Hotel check-in\n∙ Leisure time followed by a scenic sunset at Jimbaran Beach\n\nDay 2 – Southern Fun & Ocean Views\n∙ Banana boat ride at Tanjung Benoa\n∙ Chill and take photos at Melasti Beach\n∙ Evening Kecak dance performance at Uluwatu Temple\n\nDay 3 – Wildlife Adventure & Ubud Culture\n∙ Explore Bali Safari & Marine Park\n∙ Visit the playful residents at Monkey Forest\n∙ Stroll around Tegalalang Rice Terrace\n\nDay 4 – North Bali Wonders\n∙ Early morning dolphin tour at Lovina Beach\n∙ Explore scenic Pura Ulun Danu Beratan\n\nDay 5 – Highland Healing & Culture\n∙ Drive to Kintamani highlands with Mt. Batur view\n∙ Visit the holy Tampak Siring Temple (Tirta Empul)\n∙ Soak and unwind at natural hot springs\n\nDay 6 – Departure Day\n∙ Breakfast, leisure time, hotel check-out\n∙ Transfer to airport','Private air-conditioned vehicle with English-speaking driver\nAdult entrance tickets to Bali Safari & Marine Park\nEntrance tickets to all mentioned destinations\nDolphin boat tour at Lovina\nBanana boat activity (1 round per person)\nBottled mineral water during tours\nAirport pick-up and drop-off','5 nights stay at family-friendly hotel or villa\nDaily breakfast\nLunch and dinner\nPersonal expenses (snacks, souvenirs, laundry, etc.)\nEntrance tickets for children:\n∙ Bali Safari child ticket : IDR 250,000\nGratuities for driver/guide (optional)\n\n',NULL,'Minimum 2 participants required\nItinerary may be adjusted depending on weather or attraction availability\n50% deposit required to confirm booking\nFree cancellation up to 7 days prior to arrival\nNote: Prices are for adult tickets. Children require additional entrance fees.\nBali Safari child ticket: IDR 250,000\nOther attractions may vary by age and height — please inquire upon booking.\n\n','tour-packages/01KN1P7YV5FP7VV6G62YEKAQXK.jpg',NULL,5220000.00,3650000.00,3220000.00,NULL,'6 Day 5 Night','Bali',NULL,5.0,'fa-children','Family',1,0,25,'2026-03-31 10:15:19','2026-04-02 13:44:35'),(63,1,5,'UTV BUGGY ADVENTURE – SINGLE RIDE EXPERIENCE','Off-Road Jungle Track, Mud Splash & Ultimate Bali Buggy Thrill','utv-buggy-adventure-single-ride-experience','Experience the ultimate off-road adventure in Bali with our Buggy Bali Adventure – Single Ride. Drive your own buggy through challenging jungle tracks, muddy terrains, rivers, and hidden trails. Perfect for thrill seekers who want to explore Bali’s natural landscape in a fun, adrenaline-filled way. No prior experience needed—just get ready to ride!','1. Single ride buggy (no sharing – 1 person per buggy)\n2. Challenging jungle, mud, and off-road tracks\n3. Drive through rivers, tunnels, and forest trails\n4. Professional instructor and full safety briefing\n5. Suitable for beginners and experienced riders\n6. Hotel pick-up and drop-off included','1. Arrival at Buggy Base Camp\n2. Registration and safety briefing\n3. Equipment fitting (helmet & boots)\n4. Test drive session\n5. Start Buggy Adventure (jungle, mud track, river, tunnel)\n6. Finish ride and return to base camp\n7. Shower and refresh\n8. Return transfer to hotel','1. Buggy single ride (1 person per buggy)\n2. Private hotel transfer (pick-up & drop-off)\n3. Professional instructor\n4. Safety equipment (helmet & boots)\n5. Insurance coverage\n6. Shower facilities\n7. Towel and locker','1. Personal expenses\n2. Meals / lunch\n3. Photo and video documentation (GoPro)\n4. Tips / gratuities',NULL,'Basic driving ability required\nNot recommended for pregnant women\nNot suitable for participants with serious medical conditions\nParticipants must follow all safety instructions\nActivity operates in all weather conditions\nAdvance booking is required','tour-packages/01KPXG9EMVC2Y20VGTPQBW76HD.png',NULL,1200000.00,1075000.00,950000.00,NULL,'Half Day','Ubud, Bali',NULL,5.0,'fa-camera','Adventure',1,0,49,'2026-04-23 15:45:42','2026-05-12 06:02:47'),(64,1,5,'UTV BUGGY ADVENTURE – TANDEM RIDE EXPERIENCE IN UBUD','Best Bali Buggy Ride for Couples – Jungle Track, Mud Splash & Off-Road Adventure','utv-buggy-adventure-tandem-ride-experience-in-ubud','Enjoy the best Buggy Bali Adventure tandem ride in Ubud. Drive through jungle tracks, mud, rivers, and tunnels with hotel transfer included. Perfect for couples and friends.','1. Tandem ride buggy (2 persons in 1 buggy)\n2. Perfect for couples and friends\n3. Exciting jungle, mud, and off-road tracks\n4. Drive through rivers, tunnels, and forest trails\n5. Professional instructor and safety briefing\n6. Hotel pick-up and drop-off included\n7. Safe and beginner-friendly adventure','1. Hotel pick-up (private car)\n2. Arrival at Buggy Base Camp in Ubud\n3. Registration and safety briefing\n4. Equipment fitting (helmet and boots)\n5. Test drive session\n6. Start Buggy Adventure (jungle, mud track, river, tunnel)\n7. Finish ride and return to base camp\n8. Shower and refresh\n9. Return transfer to hotel','1. Tandem buggy (2 persons per buggy)\n2. Private hotel transfer (pick-up and drop-off)\n3. Professional instructor\n4. Safety equipment (helmet and boots)\n5. Insurance coverage\n6. Shower facilities\n7. Towel and locker\n8. Lunch','1. Personal expenses\n2. Photo and video documentation (GoPro)\n3. Tips / gratuities',NULL,'1. Minimum age: 6 years old (as passenger)\n2. Minimum age for driver: 12 years old\n3. Maximum combined weight: 180 kg per buggy\n4. Basic driving ability required for driver\n5. Not recommended for pregnant women\n6. Not suitable for participants with serious medical conditions\n7. Participants must follow all safety instructions\n8. Activity operates in all weather conditions\n9. Advance booking is required','tour-packages/01KPXJJT4BACESBD7DA0TTBXKM.png',NULL,950000.00,850000.00,760000.00,NULL,'Half Day','Ubud, Bali',NULL,NULL,NULL,NULL,1,0,0,'2026-04-23 16:25:46','2026-08-04 08:38:12'),(65,1,5,'MOUNT BATUR JEEP SUNRISE','Best Bali Jeep Sunrise Tour – Off-Road Volcano Adventure in Kintamani','mount-batur-jeep-sunrise','Experience the iconic Mount Batur sunrise without hiking on this Kintamani Jeep Tour. Ride a 4WD jeep through volcanic terrain, witness a breathtaking sunrise above the clouds, and explore the famous black lava and black sand areas. This adventure is perfect for those who want a unique Bali experience with less effort but maximum views.','1. Sunrise view at Mount Batur without trekking\n2. 4WD jeep adventure on volcanic terrain\n3. Explore black lava and black sand fields\n4. Stunning panoramic views of Mount Batur and Lake Batur\n5. Professional local driver and guide\n6. Hotel pick-up and drop-off included\n7. Perfect for all ages and fitness levels','1. Early morning hotel pick-up (private car)\n2. Arrival at jeep starting point (Kintamani area)\n3. Transfer to 4WD jeep and short briefing\n4. Sunrise point at Mount Batur (enjoy sunrise view)\n5. Light breakfast at sunrise point\n6. Explore black lava area\n7. Continue to black sand area\n8. Return to starting point\n9. Return transfer to hotel','1. 4WD jeep tour ( private based )\n2. Private hotel transfer (pick-up and drop-off)\n3. Professional driver/guide\n4. Sunrise breakfast (simple meal)\n5. Entrance fee to Kintamani area\n6. Drinking water','1. Personal expenses\n2. Additional meals\n3. Hot spring ticket (optional)\n4. Tips / gratuities\n5. Photo and video documentation',NULL,'1. Not recommended for pregnant women\n2. Not suitable for participants with serious medical conditions\n3. Warm jacket recommended due to cold temperature\n4. Activity operates in all weather conditions\n5. Sunrise view depends on weather conditions\n6. Advance booking is required','tour-packages/01KPXKDCDD0ADT83VJ34JZGRF6.png',NULL,1133000.00,860000.00,750000.00,NULL,'1 Day','Kintamani, Bali',NULL,5.0,'fa-camera','Experience',1,0,0,'2026-04-23 16:40:17','2026-04-23 16:50:11'),(66,1,5,'RAFTING BALI ADVENTURE – AYUNG RIVER UBUD EXPERIENCE','Best Bali Rafting Experience – Jungle River, Waterfalls & Fun Rapids','rafting-bali-adventure-ayung-river-ubud-experience','Experience an exciting Rafting Bali Adventure at Ayung River Ubud, perfect for beginners and families. Paddle through scenic jungle landscapes, pass natural waterfalls, and enjoy fun class II–III rapids. This safe and enjoyable activity offers the perfect mix of adventure and relaxation in Bali.',NULL,'1. Rafting on Ayung River – the most popular river in Bali\n2. Beautiful jungle scenery and natural waterfalls\n3. Safe rapids suitable for beginners and families\n4. Professional rafting guide and full safety briefing\n5. Clean shower facilities and lunch included\n6. Hotel pick-up and drop-off included\n\nItinerary\n\n1. Hotel pick-up (private car)\n2. Arrival at rafting base camp\n3. Registration and safety briefing\n4. Equipment fitting (helmet and life jacket)\n5. Transfer to